insert into public.media_resources_interno (resource_id, fuente, areas_trabajo, video_notas, progresion, revision, pendientes)
select id, $c$S07. Guía o fundamento general; no demuestra eficacia ni dosis de esta ficha aislada.$c$, array[$c$Equilibrio y participación cotidiana. Atención a una consigna; no se exige recordar ni responder preguntas.$c$]::text[], $c$si tiene video. Relacionado; variante sin apoyo continuo en las manos. La demostración incluye mano en cintura. No equivale a dos manos en soporte fijo; usar versión apropiada al plan.$c$, $c$Hasta 10 s; retirar manos solo por indicación profesional. Solo dentro del plan aprobado.$c$, $c$Estado: Mantener estado pendiente del manual original hasta que fisioterapia confirme variante, apoyo y dosis. La revisión editorial no reemplaza esa validación.$c$, $c$Revisión oct 2026: Registro mezclado usted/vos («Apóyelo»). Verificar que el video editado muestra las dos manos en el soporte.$c$ from public.media_resources where codigo = $c$GER-005$c$
