insert into public.media_resources (codigo, titulo, modulo, tipo, media_kind, storage_path, poster_path, drive_file_id, perfil, sabias_que, actividad, dosis, adaptacion, ten_en_cuenta, para_cerrar, niveles_cognitivos, niveles_motores, permite_doble_tarea, requiere_supervision, orden, estado_clinico, activo)
values ($c$GER-006$c$, $c$Un pie delante del otro con apoyo$c$, 'gerontogimnasia'::public.resource_modulo, 'actividad'::public.task_tipo, 'video', $c$gerontogimnasia/ger-006.mp4$c$, $c$gerontogimnasia/ger-006-poster.jpg$c$, $c$155dS7RdkJU2AXbagceYDScZdy-eDbZGz$c$, $c$Para personas con capacidad de estar de pie de forma estable con los apoyos indicados y valoración previa de esta variante. Puede adaptarse a envejecimiento normal, DCL o demencia según función y comprensión; la fase avanzada requiere pauta individual.
Funcionalidad física De pie o marcha; rutas verde o amarillo tras valoración; no usar esta variante por la ruta roja.$c$, $c$Al colocar un pie delante del otro, nuestro cuerpo necesita hacer pequeños ajustes para mantener el equilibrio. Podemos practicar con un apoyo firme y dejar espacio entre los pies, acercándolos poco a poco según la capacidad de cada persona. No hace falta que los pies se toquen para trabajar el equilibrio.$c$, $c$Prepará Baranda fija; espacio despejado. Mostrale un movimiento a la vez y permití que pare cuando lo prefiera.
Podés ver el video o demostrarle estas consignas:
1. Sujetá el apoyo con las dos manos.
2. Adelantá un pie dejando separación lateral.
3. Mantené la posición y volvé a una base amplia.$c$, $c$2 intentos de 5 s por posición. Esfuerzo suave, respiración natural; dosis ajustada por el equipo.$c$, $c$Pies más separados. Si cuesta comprender, demuestre y espere; no exigir recordar.$c$, $c$No caminar ni quitar apoyos como progresión automática. Pare ante dolor nuevo, mareo, inestabilidad o malestar; no insistir ante rechazo.$c$, $c$La posición más estrecha no es siempre la más adecuada.$c$, array[$c$preventivo$c$, $c$dcl$c$, $c$leve$c$, $c$moderada$c$, $c$avanzada$c$]::text[], array[$c$verde$c$, $c$amarillo$c$]::text[], false, null, 6, 'aprobado', true)
