insert into public.media_resources_interno (resource_id, fuente, areas_trabajo, video_notas, progresion, revision, pendientes)
select id, $c$S09. Guía o fundamento general; no demuestra eficacia ni dosis de esta ficha aislada.$c$, array[$c$Equilibrio y participación cotidiana. Atención a una consigna; no se exige recordar ni responder preguntas.$c$]::text[], $c$Si hay video. Relacionado; revisar base y soporte. La ficha empieza en semitándem y con apoyo fijo; la grabación no demuestra esa misma adaptación. No atribuir el equilibrio solo al sistema vestibular.$c$, $c$Acercar los pies o llegar a 10 s solo tras revisión. Solo dentro del plan aprobado.$c$, $c$Estado: Mantener estado pendiente del manual original hasta que fisioterapia confirme variante, apoyo y dosis. La revisión editorial no reemplaza esa validación.$c$, $c$Revisión oct 2026: Verificar que el video editado empieza en semitándem con apoyo fijo.$c$ from public.media_resources where codigo = $c$GER-006$c$
