insert into public.media_resources (codigo, titulo, modulo, tipo, media_kind, storage_path, poster_path, drive_file_id, perfil, sabias_que, actividad, dosis, adaptacion, ten_en_cuenta, para_cerrar, niveles_cognitivos, niveles_motores, permite_doble_tarea, requiere_supervision, orden, estado_clinico, activo)
values ($c$GER-007$c$, $c$Recorrido en zigzag amplio$c$, 'gerontogimnasia'::public.resource_modulo, 'actividad'::public.task_tipo, 'video', $c$gerontogimnasia/ger-007.mp4$c$, $c$gerontogimnasia/ger-007-poster.jpg$c$, $c$1c31SiJ7VOZkdcMMDzMOIaFFlaPl4Kf-f$c$, $c$Para personas con capacidad de estar de pie y caminar de forma estable con los apoyos indicados y valoración previa de esta variante. Puede adaptarse a envejecimiento normal, DCL o demencia según función y comprensión; la fase avanzada requiere pauta individual.
Funcionalidad física De pie o marcha; rutas verde o amarillo tras valoración; no usar esta variante por la ruta roja.$c$, $c$Al caminar por la casa, muchas veces cambiamos de dirección para rodear una mesa o pasar entre los muebles. Practicar un recorrido en zigzag amplio nos permite trabajar el equilibrio y la coordinación que necesitamos para hacer estos cambios de dirección en la vida diaria.$c$, $c$Prepará Marcas visibles fuera de la trayectoria; recorrido amplio y plano. Mostrale un movimiento a la vez y permití que pare cuando lo prefiera.
Podés ver el video o demostrarle estas consignas:
1. Observá con el acompañante dónde comienza y termina.
2. Caminá rodeando las marcas con giros amplios.
3. Terminá y descansá antes de repetir.$c$, $c$1 recorrido de 30–60 s; pausa de 1 min. Esfuerzo suave, respiración natural; dosis ajustada por el equipo.$c$, $c$Menos cambios de dirección y más espacio. Si cuesta comprender, demuestre y espere; no exigir recordar.$c$, $c$No poner obstáculos bajo los pies ni utilizar pesos en brazos o piernas sin prescripción. Pare ante dolor nuevo, mareo, inestabilidad o malestar; no insistir ante rechazo.$c$, $c$Un recorrido claro permite concentrarse en caminar.$c$, array[$c$preventivo$c$, $c$dcl$c$, $c$leve$c$, $c$moderada$c$, $c$avanzada$c$]::text[], array[$c$verde$c$, $c$amarillo$c$]::text[], false, null, 7, 'aprobado', true)
on conflict (codigo) do update set titulo = excluded.titulo, modulo = excluded.modulo, tipo = excluded.tipo, media_kind = excluded.media_kind, storage_path = excluded.storage_path, poster_path = excluded.poster_path, drive_file_id = excluded.drive_file_id, perfil = excluded.perfil, sabias_que = excluded.sabias_que, actividad = excluded.actividad, dosis = excluded.dosis, adaptacion = excluded.adaptacion, ten_en_cuenta = excluded.ten_en_cuenta, para_cerrar = excluded.para_cerrar, niveles_cognitivos = excluded.niveles_cognitivos, niveles_motores = excluded.niveles_motores, permite_doble_tarea = excluded.permite_doble_tarea, requiere_supervision = excluded.requiere_supervision, orden = excluded.orden, estado_clinico = excluded.estado_clinico, activo = excluded.activo, updated_at = now();
insert into public.media_resources_interno (resource_id, fuente, areas_trabajo, video_notas, progresion, revision, pendientes)
select id, $c$S23. Guía o fundamento general; no demuestra eficacia ni dosis de esta ficha aislada.$c$, array[$c$Equilibrio y participación cotidiana. Atención a una consigna; no se exige recordar ni responder preguntas.$c$]::text[], $c$Pablo Mayo 08. Variante más exigente que la ficha. La grabación transporta pelota, ausente del guion, y no muestra ayuda de marcha. No equivale a zigzag sin carga; editar o grabar variante.$c$, $c$Añadir un giro si conserva estabilidad; sin cargas añadidas. Solo dentro del plan aprobado.$c$, $c$Estado: Mantener estado pendiente del manual original hasta que fisioterapia confirme variante, apoyo y dosis. La revisión editorial no reemplaza esa validación.$c$, $c$Revisión oct 2026: Verificar que el video editado ya no transporta la pelota.$c$ from public.media_resources where codigo = $c$GER-007$c$
