insert into public.media_resources (codigo, titulo, modulo, tipo, media_kind, storage_path, poster_path, drive_file_id, perfil, sabias_que, actividad, dosis, adaptacion, ten_en_cuenta, para_cerrar, niveles_cognitivos, niveles_motores, permite_doble_tarea, requiere_supervision, orden, estado_clinico, activo)
values ($c$GER-008$c$, $c$Separar la pierna con banda$c$, 'gerontogimnasia'::public.resource_modulo, 'actividad'::public.task_tipo, 'video', $c$gerontogimnasia/ger-008.mp4$c$, $c$gerontogimnasia/ger-008-poster.jpg$c$, $c$1oGAvso_BRGGTTIjEpuKW7grzS0GCMpHo$c$, $c$Para personas con capacidad de estar de pie de forma estable con los apoyos indicados y valoración previa de esta variante. Puede adaptarse a envejecimiento normal, DCL o demencia según función y comprensión; la fase avanzada requiere pauta individual.
Funcionalidad física De pie o marcha; rutas verde o amarillo tras valoración; no usar esta variante por la ruta roja.$c$, $c$Los músculos de los lados de la cadera nos ayudan a mantener el cuerpo estable al caminar y dar pasos hacia los lados. Al separar la pierna con una banda, trabajamos la fuerza de estos músculos, que también usamos al movernos para dejar pasar a alguien o acercarnos a una silla.$c$, $c$Prepará Apoyo fijo; banda sobre rodillas solo prescrita. Mostrale un movimiento a la vez y permití que pare cuando lo prefiera.
Podés ver el video o demostrarle estas consignas:
1. Sujetá el apoyo y mantenga el tronco erguido.
2. Separá una pierna un poco, sin inclinarse.
3. Volvé despacio y cambiá de lado.$c$, $c$1 serie de 5 por lado; pausa de 60 s. Esfuerzo suave, respiración natural; dosis ajustada por el equipo.$c$, $c$Sin banda y con recorrido corto. Si cuesta comprender, demuestre y espere; no exigir recordar.$c$, $c$No desplazar el tronco ni usar una banda que comprometa el equilibrio. Pare ante dolor nuevo, mareo, inestabilidad o malestar; no insistir ante rechazo.$c$, $c$La resistencia se elige según la persona, no según el color de la banda.$c$, array[$c$preventivo$c$, $c$dcl$c$, $c$leve$c$, $c$moderada$c$, $c$avanzada$c$]::text[], array[$c$verde$c$, $c$amarillo$c$]::text[], false, null, 8, 'aprobado', true)
