insert into public.media_resources_interno (resource_id, fuente, areas_trabajo, video_notas, progresion, revision, pendientes)
select id, $c$S05. Guía o fundamento general; no demuestra eficacia ni dosis de esta ficha aislada.$c$, array[$c$Fuerza y participación cotidiana. Atención a una consigna; no se exige recordar ni responder preguntas.$c$]::text[], $c$si tiene video. Dos movimientos en un solo video. Separar fragmentos de apertura lateral y extensión hacia atrás; comprobar banda y soporte para cada variante.$c$, $c$Resistencia o repeticiones indicadas; no combinar ambos aumentos. Solo dentro del plan aprobado.$c$, $c$Estado: Mantener estado pendiente del manual original hasta que fisioterapia confirme variante, apoyo y dosis. La revisión editorial no reemplaza esa validación.$c$, $c$Revisión oct 2026: Registro mezclado usted/vos («mantenga», «sin inclinarse»). Verificar que el video editado separa los dos movimientos.$c$ from public.media_resources where codigo = $c$GER-008$c$
