insert into public.media_resources (codigo, titulo, modulo, tipo, media_kind, storage_path, poster_path, drive_file_id, perfil, sabias_que, actividad, dosis, adaptacion, ten_en_cuenta, para_cerrar, niveles_cognitivos, niveles_motores, permite_doble_tarea, requiere_supervision, orden, estado_clinico, activo)
values ($c$GER-009$c$, $c$Apoyo de pie sobre bola$c$, 'gerontogimnasia'::public.resource_modulo, 'actividad'::public.task_tipo, 'video', $c$gerontogimnasia/ger-009.mp4$c$, $c$gerontogimnasia/ger-009-poster.jpg$c$, $c$1GEke_2pB22DLEHBzC59aKsnh-Uj0jD-7$c$, $c$Para personas con capacidad de estar de pie de forma estable con los apoyos indicados y valoración previa de esta variante. Puede adaptarse a envejecimiento normal, DCL o demencia según función y comprensión; la fase avanzada requiere pauta individual.
Funcionalidad física De pie o marcha; rutas verde o amarillo tras valoración; no usar esta variante por la ruta roja.$c$, $c$Para tocar una pelota con un pie, necesitamos coordinar lo que vemos con el movimiento de la pierna, mientras la otra nos ayuda a mantener el equilibrio. Practicar con la pelota y los apoyos indicados permite trabajar estas habilidades, que también usamos al dar un paso para superar un pequeño obstáculo.$c$, $c$Prepará Soporte fijo validado por fisioterapia; pelota y sistema de inmovilización preparados por el profesional; suelo antideslizante. No improvisar montaje doméstico. Mostrale un movimiento a la vez y permití que pare cuando lo prefiera.
Podés ver el video o demostrarle estas consignas:
1. Usá el soporte fijo y la pelota inmovilizada que el profesional haya preparado para esta variante.
2. Mantené un pie firme en el suelo y tocá la pelota suavemente con el otro, sin descargar peso ni hacerla rodar.
3. Volvé a apoyar ambos pies antes de alternar. No hagás círculos sobre la pelota en esta variante.$c$, $c$propuesta inicial de 3 apoyos por pie, con pausa de 60 s o antes si es necesario. Movimiento lento y respiración natural; dosis individual autorizada por el equipo.$c$, $c$Acercar la bola, reducir las repeticiones y demostrar un pie a la vez. Si no controla la bola o el equilibrio, sustituirla por una referencia plana y estable según el plan profesional.$c$, $c$No iniciar como actividad autoguiada. Requiere enseñanza presencial y acompañamiento entrenado. No descargar peso sobre pelota o conos, ni usar una silla móvil como soporte. Si el material se mueve, parar. Detener ante dolor, mareo, inestabilidad, fatiga, confusión o rechazo.$c$, $c$La superficie y el apoyo se revisan antes de empezar.$c$, array[$c$preventivo$c$, $c$dcl$c$, $c$leve$c$, $c$moderada$c$, $c$avanzada$c$]::text[], array[$c$verde$c$, $c$amarillo$c$]::text[], false, $c$ayuda_fisica_entrenada$c$, 9, 'aprobado', true)
on conflict (codigo) do update set titulo = excluded.titulo, modulo = excluded.modulo, tipo = excluded.tipo, media_kind = excluded.media_kind, storage_path = excluded.storage_path, poster_path = excluded.poster_path, drive_file_id = excluded.drive_file_id, perfil = excluded.perfil, sabias_que = excluded.sabias_que, actividad = excluded.actividad, dosis = excluded.dosis, adaptacion = excluded.adaptacion, ten_en_cuenta = excluded.ten_en_cuenta, para_cerrar = excluded.para_cerrar, niveles_cognitivos = excluded.niveles_cognitivos, niveles_motores = excluded.niveles_motores, permite_doble_tarea = excluded.permite_doble_tarea, requiere_supervision = excluded.requiere_supervision, orden = excluded.orden, estado_clinico = excluded.estado_clinico, activo = excluded.activo, updated_at = now();
insert into public.media_resources_interno (resource_id, fuente, areas_trabajo, video_notas, progresion, revision, pendientes)
select id, $c$S23. Guía o fundamento general; no demuestra eficacia ni dosis de esta ficha aislada.$c$, array[$c$Equilibrio con apoyo, coordinación de miembros inferiores, alternancia izquierda-derecha y atención a una consigna motora. No añadir una tarea cognitiva simultánea a esta variante.$c$]::text[], $c$si hay video. No usar completa sin revisión de técnica, apoyo y superficie móvil.$c$, $c$Aumentar gradualmente las alternancias solo después de comprobar control y tolerancia, dentro del plan aprobado. Mantener el apoyo de la silla y el control de la bola.$c$, $c$Cambio conservador de la variante: soporte fijo, contacto sin carga; en GER-044 pelota inmovilizada; en GER-045 sin cruce automático. No equivale a aprobar el ejercicio original sobre material móvil. Estado: Mantener estado pendiente del manual original hasta que fisioterapia confirme variante, apoyo y dosis. La revisión editorial no reemplaza esa validación.$c$, $c$Revisión oct 2026: Menciona GER-044 y GER-045, que no existen. El título no describe la consigna (tocar una pelota inmovilizada sin cargar peso). «Progresión» menciona el apoyo de la silla aunque se prohíbe usar silla móvil como soporte. Verificar la superficie móvil en el video editado.$c$ from public.media_resources where codigo = $c$GER-009$c$
on conflict (resource_id) do update set fuente = excluded.fuente, areas_trabajo = excluded.areas_trabajo, video_notas = excluded.video_notas, progresion = excluded.progresion, revision = excluded.revision, pendientes = excluded.pendientes, updated_at = now();

insert into public.media_resources (codigo, titulo, modulo, tipo, media_kind, storage_path, poster_path, drive_file_id, perfil, sabias_que, actividad, dosis, adaptacion, ten_en_cuenta, para_cerrar, niveles_cognitivos, niveles_motores, permite_doble_tarea, requiere_supervision, orden, estado_clinico, activo)
values ($c$GER-010$c$, $c$Introducción$c$, 'gerontogimnasia'::public.resource_modulo, 'actividad'::public.task_tipo, 'video', $c$gerontogimnasia/ger-010.mp4$c$, $c$gerontogimnasia/ger-010-poster.jpg$c$, $c$11i38S_xbG7djVnWxMKH9U8cQs3GUirOT$c$, $c$Para las personas que inician las actividades de gerontogimnasia de IntegraMente en Casa y sus familiares o cuidadores.
Funcionalidad física Todas las rutas: verde, amarillo y rojo. Esta actividad consiste en ver un video introductorio; no requiere realizar ejercicios.$c$, $c$Para levantarnos de una silla, caminar o alcanzar un objeto, nuestro cerebro y nuestros músculos trabajan juntos. La gerontogimnasia nos permite trabajar movimientos que usamos todos los días, con actividades adaptadas a las capacidades de cada persona.$c$, $c$Prepará un espacio cómodo, con buena iluminación y sin distracciones. Ajustá el volumen para escuchar con claridad.
Antes de comenzar con los ejercicios, te invitamos a conocer esta parte del programa.
Podés ver el video de introducción junto a tu familiar:
• Conocé qué es la gerontogimnasia y cuál es su propósito dentro de IntegraMente en Casa.
• Observá cómo se relacionan el movimiento y las habilidades mentales en las actividades que presenta el video.
• Al terminar, continuá con las actividades asignadas en la aplicación.$c$, $c$No aplica una dosis de ejercicio. Ver el video al comenzar esta sección y volver a consultarlo cuando lo necesiten.$c$, $c$Podés pausar el video y explicar una idea a la vez con palabras sencillas. Si resulta difícil seguirlo, el familiar o cuidador puede verlo primero y compartir una explicación breve, sin exigir que la persona recuerde el contenido.$c$, $c$Este video presenta el propósito del programa. Para realizar los ejercicios, seguí las indicaciones de cada actividad y los apoyos establecidos para la persona. Las tareas de movimiento y los retos mentales se combinan únicamente cuando esté indicado.$c$, $c$Cada persona tiene su propio ritmo. Empezamos conociendo las actividades y avanzamos paso a paso.$c$, array[$c$preventivo$c$, $c$dcl$c$, $c$leve$c$, $c$moderada$c$, $c$avanzada$c$]::text[], array[$c$verde$c$, $c$amarillo$c$, $c$rojo$c$]::text[], false, null, 0, 'aprobado', true)
on conflict (codigo) do update set titulo = excluded.titulo, modulo = excluded.modulo, tipo = excluded.tipo, media_kind = excluded.media_kind, storage_path = excluded.storage_path, poster_path = excluded.poster_path, drive_file_id = excluded.drive_file_id, perfil = excluded.perfil, sabias_que = excluded.sabias_que, actividad = excluded.actividad, dosis = excluded.dosis, adaptacion = excluded.adaptacion, ten_en_cuenta = excluded.ten_en_cuenta, para_cerrar = excluded.para_cerrar, niveles_cognitivos = excluded.niveles_cognitivos, niveles_motores = excluded.niveles_motores, permite_doble_tarea = excluded.permite_doble_tarea, requiere_supervision = excluded.requiere_supervision, orden = excluded.orden, estado_clinico = excluded.estado_clinico, activo = excluded.activo, updated_at = now();
insert into public.media_resources_interno (resource_id, fuente, areas_trabajo, video_notas, progresion, revision, pendientes)
select id, $c$Guion audiovisual «Introducción y Propósito», proporcionado por el equipo de IntegraMente.$c$, array[$c$Familiarización con el programa y comprensión del propósito de la gerontogimnasia. No corresponde a una sesión de ejercicio ni a una evaluación cognitiva.$c$]::text[], $c$Introducción y Propósito. Vincular este recurso con GER-010 y mostrar el título «Introducción».$c$, $c$No aplica progresión física. Después del video, dirigir a las actividades asignadas según las capacidades y necesidades de apoyo de cada persona.$c$, $c$Recurso introductorio. Mantener el código GER-010 para conservar la organización del documento. En la aplicación, mostrarlo antes del primer ejercicio, independientemente de su numeración, y dejarlo disponible para consultas posteriores. Estado: Guion de introducción identificado. Pendiente de vincular el archivo audiovisual correspondiente en la aplicación.$c$, $c$Revisión oct 2026: El video dura lo mismo que el de GER-001 (37,1 s); confirmar que es el archivo correcto (el contenido es distinto).$c$ from public.media_resources where codigo = $c$GER-010$c$
on conflict (resource_id) do update set fuente = excluded.fuente, areas_trabajo = excluded.areas_trabajo, video_notas = excluded.video_notas, progresion = excluded.progresion, revision = excluded.revision, pendientes = excluded.pendientes, updated_at = now();

