insert into public.media_resources (codigo, titulo, modulo, tipo, media_kind, storage_path, poster_path, drive_file_id, perfil, sabias_que, actividad, dosis, adaptacion, ten_en_cuenta, para_cerrar, niveles_cognitivos, niveles_motores, permite_doble_tarea, requiere_supervision, alergenos, exclusiones, grupo_rotacion, requiere_plan_individual, orden, estado_clinico, activo)
values ($c$PRE-001$c$, $c$Prepará un gallo pinto con olores frescos$c$, 'nutricion'::public.resource_modulo, 'actividad'::public.task_tipo, null, null, null, null, $c$Para familiares y cuidadores de personas con envejecimiento normal, deterioro cognitivo leve o síndromes demenciales en etapas leves y moderadas. La preparación y el apoyo deben ajustarse a las necesidades de cada persona.$c$, $c$El arroz y los frijoles pueden formar parte de un desayuno variado. Los olores frescos dan sabor y ayudan a usar menos sazonadores con sodio.$c$, $c$Esta semana, prepará el pinto con cebolla, culantro y chile dulce. Usá aceite de oliva o canola en lugar de manteca y probá antes de agregar sal. Repetilo en tres desayunos, si se ajusta a tu plan.$c$, null, null, null, $c$Los cambios pequeños también cuentan.$c$, array[$c$preventivo$c$, $c$dcl$c$, $c$leve$c$, $c$moderada$c$]::text[], null, false, null, null, null, null, false, 1, 'aprobado', true)
