insert into public.media_resources_interno (resource_id, fuente, fuente_url, reglas, pendientes)
select id, $c$DASH y cuidado cardiovascular. Reducir sodio puede ayudar a controlar la presión; comparar porciones equivalentes y distinguir miligramos de porcentaje de valor diario [1, 8].$c$, null, $c$Destinatarios: Prevención y DCL. Adaptar apoyo y seguridad según la persona. Asignación y precauciones: Adaptar arroz, frijoles y aguacate cuando exista una restricción individual de carbohidratos, potasio o fósforo. Ante inapetencia, priorizar una alimentación suficiente.$c$, $c$Texto. Ninguno. Título original con audiencia: (Envejecimiento normal, deterioro cognitivo leve y demencia leve). Revisión oct 2026: «¿Para quién?» incluye demencia, pero sus notas dicen «Prevención y DCL» y el título dice «…y demencia leve». Referencias numeradas [1–8] sin lista de referencias.$c$ from public.media_resources where codigo = $c$PRE-001$c$
