insert into public.media_resources (codigo, titulo, modulo, tipo, media_kind, storage_path, poster_path, drive_file_id, perfil, sabias_que, actividad, dosis, adaptacion, ten_en_cuenta, para_cerrar, niveles_cognitivos, niveles_motores, permite_doble_tarea, requiere_supervision, alergenos, exclusiones, grupo_rotacion, requiere_plan_individual, orden, estado_clinico, activo)
values ($c$PRE-005$c$, $c$Agregá hojas verdes a una comida$c$, 'nutricion'::public.resource_modulo, 'actividad'::public.task_tipo, null, null, null, null, $c$Para familiares y cuidadores de personas con envejecimiento normal, deterioro cognitivo leve o síndromes demenciales en etapas leves, moderadas y severas. Adaptar la actividad y el apoyo a las necesidades de cada persona.$c$, $c$Un estudio de seguimiento de 960 personas mayores relacionó un mayor consumo de hojas verdes con un deterioro cognitivo más lento.$c$, $c$Esta semana, agregá hojas verdes a tres comidas de tu familiar. Lavá bien espinaca, acelga, mostaza o lechuga. Podés ofrecer media taza cocida o una taza cruda, según la textura adecuada para él o ella. Una opción es incorporarlas a un huevo o picadillo conocido.$c$, null, null, $c$Si toma warfarina, coordiná cambios en la cantidad de hojas verdes con su equipo tratante; no hace falta eliminarlas. Si tiene restricción de potasio o cálculos por oxalato, consultá qué hojas y cantidades convienen. Con dificultad para tragar, seguí la textura indicada.$c$, $c$Un ingrediente conocido puede darle variedad a una comida de siempre.$c$, array[$c$preventivo$c$, $c$dcl$c$, $c$leve$c$, $c$moderada$c$, $c$avanzada$c$]::text[], null, false, null, null, null, $c$hojas_verdes$c$, false, 5, 'aprobado', true)
