insert into public.media_resources (codigo, titulo, modulo, tipo, media_kind, storage_path, poster_path, drive_file_id, perfil, sabias_que, actividad, dosis, adaptacion, ten_en_cuenta, para_cerrar, niveles_cognitivos, niveles_motores, permite_doble_tarea, requiere_supervision, alergenos, exclusiones, grupo_rotacion, requiere_plan_individual, orden, estado_clinico, activo)
values ($c$PRE-006$c$, $c$Una merienda con frutos secos$c$, 'nutricion'::public.resource_modulo, 'actividad'::public.task_tipo, null, null, null, null, $c$Para familiares y cuidadores de personas con envejecimiento normal, deterioro cognitivo leve o síndromes demenciales en etapas leves, moderadas y severas. Adaptar la actividad y el apoyo a las necesidades de cada persona.$c$, $c$En un ensayo con personas mayores, la alimentación mediterránea acompañada de frutos secos o aceite de oliva mostró resultados favorables en algunas medidas cognitivas frente al grupo control. Se estudió el patrón completo, no un fruto seco aislado.$c$, $c$Si tu familiar mastica y traga con seguridad, ofrecé un puñito pequeño de nueces, almendras o semillas de marañón sin sal, de unos 30 g. Probalo en dos meriendas de la semana en lugar de galletas. Serví la cantidad en un recipiente y guardá el paquete.$c$, null, null, $c$No ofrezcás frutos secos enteros si tiene disfagia, dificultades dentales o de masticación. Las versiones molidas también deben ajustarse a su evaluación. Evitalos si tiene alergia y consultá la cantidad si hay restricciones renales.$c$, $c$Una porción servida facilita disfrutar la merienda.$c$, array[$c$preventivo$c$, $c$dcl$c$, $c$leve$c$, $c$moderada$c$, $c$avanzada$c$]::text[], null, false, null, array[$c$frutos_secos$c$]::text[], array[$c$disfagia_sin_textura$c$]::text[], null, false, 6, 'aprobado', true)
