select id, $c$Valls-Pedret y colaboradores, 2015. Mediterranean Diet and Age-Related Cognitive Decline. Ensayo PREDIMED; consultar versión corregida en 2018. Resultados del patrón completo en personas sin deterioro cognitivo inicial y con riesgo cardiovascular.$c$, $c$https://jamanetwork.com/journals/jamainternalmedicine/fullarticle/2293082$c$, null, $c$Foto de 30 g opcional. La asignación depende de seguridad para masticar y tragar, no únicamente del estadio cognitivo.$c$ from public.media_resources where codigo = $c$PRE-006$c$
