insert into public.media_resources_interno (resource_id, fuente, fuente_url, reglas, pendientes)
select id, $c$NIDDK, NIH. Eating Diet and Nutrition for Constipation. Recomendaciones generales sobre fibra y líquidos; no evalúa esta receta o fruta específica.$c$, $c$https://www.niddk.nih.gov/health-information/digestive-diseases/constipation/eating-diet-nutrition$c$, null, $c$Pendiente de nutrición: receta específica para chía y para chan con cantidades, líquido y tiempo de hidratación. La acción con linaza requiere una cantidad ya indicada. No anunciar ni asignar una receta inexistente. Revisión oct 2026: No existe la receta de chía/chan que la ficha remite a nutrición. Porciones pendientes de nutrición (ficha con plan individual).$c$ from public.media_resources where codigo = $c$PRE-021$c$
