select id, $c$Volkert y colaboradores, 2024. ESPEN guideline on nutrition and hydration in dementia Update 2024. Guía clínica; muchas recomendaciones son de buena práctica por evidencia experimental limitada.$c$, $c$https://pubmed.ncbi.nlm.nih.gov/38772068/$c$, null, $c$Texto autosuficiente. No es rehabilitación de deglución ni una estrategia para reducir ingesta.$c$ from public.media_resources where codigo = $c$PRE-023$c$
