select id, $c$NIDDK, NIH. Healthy Eating for Adults with Chronic Kidney Disease. Orientación sobre preparación y restricciones individualizadas.$c$, $c$https://www.niddk.nih.gov/health-information/kidney-disease/chronic-kidney-disease-ckd/healthy-eating-adults-chronic-kidney-disease$c$, null, $c$Video opcional. No se prescribe vapor en quienes necesitan técnicas de reducción de potasio.$c$ from public.media_resources where codigo = $c$PRE-028$c$
