insert into public.media_resources_interno (resource_id, fuente, fuente_url, reglas, pendientes)
select id, $c$Organización Mundial de la Salud. Healthy diet. Guía general de alimentación; adaptar a necesidades individuales y no extrapolar a tratamiento de demencia.$c$, $c$https://www.who.int/news-room/fact-sheets/detail/healthy-diet$c$, null, $c$Si se quiere enseñar la preparación, falta receta con cantidades, método, tiempo, temperatura y porción. La versión actual se dirige a quien ya sabe prepararla. Revisión oct 2026: Porciones pendientes de nutrición (ficha con plan individual).$c$ from public.media_resources where codigo = $c$PRE-029$c$
