insert into public.media_resources (codigo, titulo, modulo, tipo, media_kind, storage_path, poster_path, drive_file_id, perfil, sabias_que, actividad, dosis, adaptacion, ten_en_cuenta, para_cerrar, niveles_cognitivos, niveles_motores, permite_doble_tarea, requiere_supervision, alergenos, exclusiones, grupo_rotacion, requiere_plan_individual, orden, estado_clinico, activo)
values ($c$PRE-030$c$, $c$Organizá los alimentos en tu plato$c$, 'nutricion'::public.resource_modulo, 'actividad'::public.task_tipo, null, null, null, null, $c$Para familiares y cuidadores de personas con envejecimiento normal, deterioro cognitivo leve o síndromes demenciales en etapas leves y moderadas. Adaptar la actividad y el apoyo a las necesidades de cada persona.$c$, $c$El método del plato, utilizado en educación sobre diabetes, ofrece una guía visual para distribuir vegetales, proteína y alimentos con carbohidratos. Debe ajustarse cuando cambian las necesidades de la persona.$c$, $c$En un almuerzo de esta semana, probá organizar el plato de tu familiar con una mitad de vegetales sin almidón, un cuarto de proteína y un cuarto de arroz, pasta, tortilla o tubérculo. Las leguminosas aportan proteína y carbohidratos: ubicá su porción según el plan indicado.$c$, null, null, $c$Si hay bajo peso, poco apetito, desnutrición o enfermedad renal, esta distribución puede necesitar cambios. No llenés el plato de vegetales a costa de la energía o proteína que necesita.$c$, $c$Usá el plato como una guía flexible, no como una regla rígida.$c$, array[$c$preventivo$c$, $c$dcl$c$, $c$leve$c$, $c$moderada$c$]::text[], null, false, null, null, array[$c$desnutricion$c$]::text[], null, false, 30, 'aprobado', true)
