select id, $c$NIDDK, NIH. Eating Diet and Nutrition for Constipation. Recomendaciones generales sobre fibra y líquidos; no evalúa esta receta o fruta específica.$c$, $c$https://www.niddk.nih.gov/health-information/digestive-diseases/constipation/eating-diet-nutrition$c$, null, $c$Texto autosuficiente. No indicar tragar las semillas sin morderlas.$c$ from public.media_resources where codigo = $c$PRE-038$c$
