select id, $c$Organización Mundial de la Salud. Healthy diet. Guía general de alimentación; adaptar a necesidades individuales y no extrapolar a tratamiento de demencia.$c$, $c$https://www.who.int/news-room/fact-sheets/detail/healthy-diet$c$, null, $c$Acordar medida con PRE-012 cuando no haya plan individual. No sumar una cucharada diaria sin valorar el resto de la alimentación. Revisión oct 2026: Unificar la medida de aceite con PRE-012. Porciones pendientes de nutrición (ficha con plan individual).$c$ from public.media_resources where codigo = $c$PRE-039$c$
