-- ─── Recursos cognitivos ───
update public.media_resources set titulo = $c$Recuerdo el camino$c$, detalle = null, perfil = $c$Preventivo · Deterioro cognitivo leve. · Demencia Leve$c$, materiales = $c$Fotografía de un lugar conocido, como un parque, supermercado, iglesia, lugar significativo para la persona, si está disponible. Sino tienes fotos también pueden conversar sobre un sitio familiar, como la iglesia, el parque o un supermercado cercano, sin necesidad de usar imágenes. Papel y lápiz son opcionales.$c$, pasos = $c$["Elijan un lugar que la persona conozca bien. Si tienen una fotografía, pueden utilizarla para iniciar la conversación.", "Pregunten: «¿Cómo llegaríamos desde la casa hasta la iglesia?» o «¿Cuál supermercado queda cerca y por dónde iríamos?».", "Acompañen el recorrido con preguntas sencillas: «¿Por dónde empezamos?», «¿Qué lugares veríamos en el camino?» o «¿Hacia dónde seguimos después?».", "Si les resulta agradable, dibujen juntos un camino sencillo y señalen algunos lugares de referencia."]$c$::jsonb, ayuda = $c$Ofrezcan una pista o dos opciones: «¿Pasaríamos por el parque o por la escuela?». No hace falta recordar todos los nombres ni describir la ruta con exactitud; lo importante es participar y compartir. El recorrido se realiza mediante la conversación o el dibujo, sin necesidad de salir de casa$c$, adaptacion_por_etapa = null, precaucion = null, ciencia = $c${"gancho": "¿Sabías que recordar lugares que se frecuentaron a lo largo de la vida puede ayudar a mantener activa la mente?", "evidencia": "Un metaanálisis de Saragih y colaboradores (2022), que incluyó 29 estudios con 3.102 participantes, encontró resultados favorables asociados a esta intervención.", "cierre": "Por eso, hoy vamos a recordar lugares conocidos, pensar cómo llegaríamos hasta ellos y ejercitar nuestra memoria, orientación y lenguaje. 🏡🗺️"}$c$::jsonb, extras = null, niveles_cognitivos = array[$c$preventivo$c$, $c$dcl$c$, $c$leve$c$]::text[], duracion = $c$10 min a 15 min$c$, frecuencia = $c$De 2 a 3 veces por semana$c$, orden = 1, estado_clinico = 'aprobado', adaptacion = null, por_que = null, objetivo = null, progresion = null, requisito = null, dominios = null, updated_at = now() where codigo = $c$COG-001$c$;
insert into public.media_resources_interno (resource_id, objetivo, objetivo_esperado, areas_trabajo, progresion, reglas, etiquetas)
select id, $c$Estimular la orientación espacial, la planificación de recorridos y la memoria autobiográfica mediante la descripción de rutas hacia lugares familiares.$c$, $c$Favorecer la organización mental de recorridos familiares mediante la identificación de lugares, la descripción de rutas y la evocación de experiencias personales.$c$, array[$c$Orientación espacial$c$, $c$Planificación y Flexibilidad$c$, $c$Memoria autobiográfica$c$, $c$Atención$c$, $c$Lenguaje$c$]::text[], null, $c$Preventivo y DCL Utilizar un lugar familiar y permitir pistas visuales o verbales sin exigir precisión.$c$, array[$c$Orientación espacial$c$, $c$planificación$c$, $c$secuenciación$c$, $c$memoria autobiográfica$c$, $c$lenguaje$c$]::text[] from public.media_resources where codigo = $c$COG-001$c$
on conflict (resource_id) do update set objetivo = excluded.objetivo, objetivo_esperado = excluded.objetivo_esperado, areas_trabajo = excluded.areas_trabajo, progresion = excluded.progresion, reglas = excluded.reglas, etiquetas = excluded.etiquetas, updated_at = now();

update public.media_resources set titulo = $c$Mi lugar de vivienda antes y ahora$c$, detalle = $c$Hoy realizaremos «Mi lugar de vivienda antes y ahora». Vamos a recordar un lugar donde la persona haya vivido y compartir algunas historias. Si tienen fotografías, pueden acompañar la conversación; si no, sus recuerdos serán el punto de partida.$c$, perfil = $c$Preventivo. · Deterioro cognitivo leve. · Demencia leve, con apoyo visual y preguntas breves.$c$, materiales = $c$Fotografías antiguas o actuales del barrio, si están disponibles. También puede realizarse únicamente mediante la conversación, recordando cómo era el lugar.$c$, pasos = $c$["Elijan un barrio o comunidad que haya sido significativo para la persona.", "Inviten a recordar: «¿Cómo era el lugar donde vivía?», «¿Qué había cerca de su casa?» o «¿Qué le gustaba de ese lugar?».", "Si tienen fotografías, obsérvenlas juntos y conversen sobre los lugares que reconoce.", "Si conoce cómo es el lugar actualmente, pregunten: «¿Qué ha cambiado?» o «¿Qué sigue parecido?». Si no lo sabe, pueden continuar compartiendo recuerdos.", "Cierren retomando algún detalle o historia que haya disfrutado contar."]$c$::jsonb, ayuda = null, adaptacion_por_etapa = $c${"preventivo": "permitir una comparación más libre.", "dcl": "hacer preguntas concretas.", "leve": "presentar una imagen a la vez y ofrecer opciones, por ejemplo: «¿Había más casas o más comercios?». Si el recuerdo genera tristeza o incomodidad, cambiar de tema."}$c$::jsonb, precaucion = null, ciencia = $c${"gancho": "¿Sabías que recordar experiencias del pasado y compartirlas mediante fotografías, preguntas o conversaciones puede ser una forma de mantener la mente activa?", "evidencia": "Una revisión Cochrane realizada por Woods y colaboradores (2018) encontró posibles beneficios de la terapia de reminiscencia en aspectos como la comunicación, la cognición, el estado de ánimo y la calidad de vida, aunque los resultados pueden variar de una persona a otra.", "cierre": "Por eso, hoy vamos a recordar momentos y experiencias significativas, ejercitando nuestra memoria y compartiendo historias de nuestra vida."}$c$::jsonb, extras = null, niveles_cognitivos = array[$c$preventivo$c$, $c$dcl$c$, $c$leve$c$]::text[], duracion = $c$10–15 minutos$c$, frecuencia = $c$2–3 veces por semana$c$, orden = 2, estado_clinico = 'aprobado', adaptacion = null, por_que = null, objetivo = null, progresion = null, requisito = null, dominios = null, updated_at = now() where codigo = $c$COG-002$c$;
insert into public.media_resources_interno (resource_id, objetivo, objetivo_esperado, areas_trabajo, progresion, reglas, etiquetas)
select id, $c$Evocar recuerdos vinculados con un barrio conocido y comparar, de manera sencilla, cómo era antes y cómo es ahora.$c$, $c$Facilitar la evocación de experiencias vinculadas con un lugar conocido y practicar la observación y comparación de cambios, sin exigir precisión histórica.$c$, array[$c$Memoria autobiográfica$c$, $c$Atención visual$c$, $c$Lenguaje$c$, $c$Flexibilidad$c$, $c$Orientación temporal$c$]::text[], $c$Conversar sobre un lugar → recordar un detalle con ayuda → describir una experiencia → comparar el antes y el ahora, si conoce ambos.$c$, $c$Preventivo, DCL y demencia leve Usar imágenes de lugares realmente familiares cuando sea posible. No discutir para demostrar si un recuerdo es correcto; validar la experiencia y ofrecer ayuda con respeto.$c$, array[$c$Memoria autobiográfica$c$, $c$atención visual$c$, $c$lenguaje$c$, $c$comparación$c$, $c$orientación temporal$c$]::text[] from public.media_resources where codigo = $c$COG-002$c$
on conflict (resource_id) do update set objetivo = excluded.objetivo, objetivo_esperado = excluded.objetivo_esperado, areas_trabajo = excluded.areas_trabajo, progresion = excluded.progresion, reglas = excluded.reglas, etiquetas = excluded.etiquetas, updated_at = now();

update public.media_resources set titulo = $c$Un día de trabajo, paso a paso$c$, detalle = $c$Hoy realizaremos «Un día de trabajo, paso a paso». Hoy vamos a recordar una actividad que la persona realizaba en su trabajo, oficio o responsabilidad cotidiana. Lo importante es conversar y ordenar ideas, no comprobar si recuerda todos los detalles.$c$, perfil = $c$Preventivo. · Deterioro cognitivo leve. · Demencia leve si la persona desea conversar sobre su vida laboral o sus responsabilidades pasadas.$c$, materiales = $c$Tarjetas con dibujos o palabras de acciones relacionadas con el oficio de la persona. Usar tarjetas en blanco para dibujar o escribir las tareas.$c$, pasos = $c$["Preguntar qué trabajo, oficio o responsabilidad le gustaría recordar.", "Invitar a mencionar algunas tareas que realizaba durante una jornada habitual.", "Anotar o dibujar de tres a cinco tareas en tarjetas separadas.", "Pedir que las coloque en un orden aproximado: qué hacía primero, después y al final.", "Conversar sobre qué tarea le resultaba más familiar o qué parte del trabajo disfrutaba, si desea compartirlo."]$c$::jsonb, ayuda = null, adaptacion_por_etapa = $c${"preventivo": "dejar que la persona organice las tareas con autonomía.", "dcl": "usar tres o cuatro tarjetas y preguntas guía.", "leve": "elegir entre dos tarjetas por vez y aceptar un orden aproximado. Evitar insistir si el tema laboral es sensible."}$c$::jsonb, precaucion = null, ciencia = $c${"gancho": "¿Sabías que recordar experiencias personales no solo permite revivir momentos importantes, sino que también implica organizar y reconstruir información de nuestra vida?", "evidencia": "Una revisión sistemática publicada en 2025 analizó 83 estudios sobre la memoria autobiográfica en personas con enfermedad de Alzheimer y encontró una relación entre esta memoria y las funciones ejecutivas, que participan en la organización y planificación de la información.", "cierre": "Por eso, hoy vamos a recordar las tareas de un trabajo u oficio y organizarlas paso a paso, ejercitando nuestra memoria, atención, lenguaje y capacidad para ordenar actividades. 🧩💼"}$c$::jsonb, extras = null, niveles_cognitivos = array[$c$preventivo$c$, $c$dcl$c$, $c$leve$c$]::text[], duracion = $c$10–15 minutos$c$, frecuencia = $c$2–3 veces por semana$c$, orden = 3, estado_clinico = 'aprobado', adaptacion = null, por_que = null, objetivo = null, progresion = null, requisito = null, dominios = null, updated_at = now() where codigo = $c$COG-003$c$;
insert into public.media_resources_interno (resource_id, objetivo, objetivo_esperado, areas_trabajo, progresion, reglas, etiquetas)
select id, $c$Evocar y organizar la secuencia de tareas de un trabajo, oficio o responsabilidad que haya sido significativa para la persona.$c$, $c$Apoyar la evocación de conocimientos y experiencias relacionados con un rol significativo y practicar la organización verbal de tareas familiares.$c$, array[$c$Memoria autobiográfica$c$, $c$Memoria semántica$c$, $c$Secuenciación$c$, $c$Lenguaje$c$, $c$Atención$c$]::text[], $c$Nombrar una tarea → recordar dos tareas → ordenarlas con ayuda → describir una jornada con inicio, desarrollo y cierre.$c$, $c$Adaptar las tarjetas al oficio o responsabilidad real de la persona. No asumir que todas las personas tuvieron un empleo formal; pueden elegirse tareas de cuido, voluntariado o labores del hogar.$c$, array[$c$Memoria autobiográfica$c$, $c$memoria semántica$c$, $c$secuenciación$c$, $c$lenguaje$c$, $c$atención$c$]::text[] from public.media_resources where codigo = $c$COG-003$c$
on conflict (resource_id) do update set objetivo = excluded.objetivo, objetivo_esperado = excluded.objetivo_esperado, areas_trabajo = excluded.areas_trabajo, progresion = excluded.progresion, reglas = excluded.reglas, etiquetas = excluded.etiquetas, updated_at = now();

update public.media_resources set titulo = $c$Palabras y expresiones de mi época$c$, detalle = $c$Hoy realizaremos «Palabras y expresiones de mi época». Vamos a recordar palabras o expresiones que se escuchaban antes. No hace falta completar todos los dichos ni saber su origen; podemos conversar sobre lo que significan o cuándo se usaban.$c$, perfil = $c$Preventivo. · Deterioro cognitivo leve. · Demencia leve, con ejemplos y opciones de respuesta.$c$, materiales = $c$Lista breve de expresiones, refranes o palabras propias de la comunidad o generación de la persona. Se pueden preparar tarjetas con una expresión por tarjeta.$c$, pasos = $c$["Presentar una expresión familiar y leerla en voz alta si hace falta.", "Preguntar si la había escuchado antes y qué cree que significa.", "Invitar a recordar quién la decía o en qué situación se utilizaba, sin exigir que recuerde a una persona específica.", "Si la persona disfruta el reto, comenzar un refrán conocido y dejar que lo complete; también puede elegir entre dos posibles finales.", "Cerrar preguntando si hay otra palabra o expresión que le gustaría compartir."]$c$::jsonb, ayuda = null, adaptacion_por_etapa = $c${"preventivo": "explorar significados y variantes regionales.", "dcl": "ofrecer una pista o ejemplo.", "leve": "trabajar con una expresión a la vez y aceptar respuestas cortas, gestos o elecciones entre opciones."}$c$::jsonb, precaucion = null, ciencia = $c${"gancho": "¿Sabías que las palabras que conocemos y su significado forman parte de nuestra memoria semántica, que nos ayuda a comprender el lenguaje y expresar nuestras ideas?", "evidencia": "Una revisión publicada en 2024 sobre intervenciones semánticas en personas mayores destaca la importancia de trabajar con palabras, conceptos y significados mediante actividades estructuradas y conversaciones relacionadas con la vida de cada persona.", "cierre": "Por eso, hoy vamos a recordar dichos, expresiones y palabras familiares, ejercitando nuestro lenguaje, la memoria semántica y la capacidad de expresar nuestros pensamientos. 💬📚"}$c$::jsonb, extras = null, niveles_cognitivos = array[$c$preventivo$c$, $c$dcl$c$, $c$leve$c$]::text[], duracion = $c$10–15 minutos$c$, frecuencia = $c$2–3 veces por semana$c$, orden = 4, estado_clinico = 'aprobado', adaptacion = null, por_que = null, objetivo = null, progresion = null, requisito = null, dominios = null, updated_at = now() where codigo = $c$COG-004$c$;
insert into public.media_resources_interno (resource_id, objetivo, objetivo_esperado, areas_trabajo, progresion, reglas, etiquetas, pendientes)
select id, $c$Estimular el lenguaje y la memoria semántica a partir de palabras, dichos o expresiones que la persona utilizaba o escuchaba en otras etapas de su vida.$c$, $c$Promover la conversación y la recuperación de palabras significativas dentro de un ambiente familiar y sin presión por acertar.$c$, array[$c$Lenguaje expresivo y comprensivo$c$, $c$Memoria semántica$c$, $c$Memoria autobiográfica$c$, $c$Atención$c$, $c$Interacción social$c$]::text[], $c$Escuchar una expresión → reconocer si resulta familiar → explicar su significado → recordar una situación en la que se utilizaba o completar un refrán conocido.$c$, $c$Elegir expresiones respetuosas y culturalmente familiares. No corregir variantes regionales ni convertir la actividad en un examen de memoria.$c$, array[$c$Lenguaje$c$, $c$memoria semántica$c$, $c$memoria autobiográfica$c$, $c$atención$c$, $c$interacción social$c$]::text[], $c$Revisión oct 2026: Verificar la cita de «La ciencia detrás» (posible confusión de la revista Folia Phoniatrica et Logopaedica con autores).$c$ from public.media_resources where codigo = $c$COG-004$c$
on conflict (resource_id) do update set objetivo = excluded.objetivo, objetivo_esperado = excluded.objetivo_esperado, areas_trabajo = excluded.areas_trabajo, progresion = excluded.progresion, reglas = excluded.reglas, etiquetas = excluded.etiquetas, pendientes = excluded.pendientes, updated_at = now();

update public.media_resources set titulo = $c$Organicemos una salida conocida$c$, detalle = $c$Hoy realizaremos «Organicemos una salida conocida». Vamos a imaginar cómo nos prepararíamos para visitar a alguien, ir al parque o asistir a una actividad que nos guste. Compartiremos ideas y organizaremos los pasos con calma, sin necesidad de salir de casa.$c$, perfil = $c$Preventivo. · Deterioro cognitivo leve. · Demencia leve, con preguntas breves y guía del familiar. · Demencia moderada con acompañamiento, si vemos que es un tema que genera angustia cambiarlo$c$, materiales = $c$No se necesitan materiales. La actividad se realiza mediante una conversación sobre una salida conocida y significativa para la persona.$c$, pasos = $c$["Elegir juntos una salida conocida: «Pensemos que vamos a visitar a un familiar. ¿Qué prepararíamos antes de salir?».", "Invitar a mencionar algunas cosas que necesitaría hacer o llevar.", "Ayudar a organizar dos o tres pasos con preguntas como: «¿Qué haríamos primero?» y «¿Qué seguiría después?».", "Si necesita una pista, ofrecer un ejemplo: «Podríamos empezar por vestirnos. ¿Qué haríamos después?».", "Conversar sobre lo que cambiaría según la ocasión: «¿Y si estuviera lloviendo?» o «¿Llevaríamos lo mismo para ir al parque?».", "Cerrar repasando juntos los pasos que mencionaron, sin exigir que los recuerde nuevamente."]$c$::jsonb, ayuda = null, adaptacion_por_etapa = null, precaucion = null, ciencia = $c${"gancho": "¿Sabías que las funciones ejecutivas nos ayudan a planificar y organizar pasos?", "evidencia": "Un metaanálisis de 2025 encontró beneficios del entrenamiento cognitivo en algunas habilidades mentales de personas mayores, como la memoria de trabajo y funciones ejecutivas.", "cierre": "Hoy vamos a recordar cómo nos preparábamos para una salida y ordenar sus pasos, ejercitando nuestra planificación, atención y memoria. 🗓️👜"}$c$::jsonb, extras = null, niveles_cognitivos = array[$c$preventivo$c$, $c$dcl$c$, $c$leve$c$, $c$moderada$c$]::text[], duracion = $c$10–15 minutos$c$, frecuencia = $c$2–3 veces por semana$c$, orden = 5, estado_clinico = 'aprobado', adaptacion = null, por_que = null, objetivo = null, progresion = null, requisito = null, dominios = null, updated_at = now() where codigo = $c$COG-005$c$;
insert into public.media_resources_interno (resource_id, objetivo, objetivo_esperado, areas_trabajo, progresion, reglas, etiquetas, pendientes)
select id, $c$Practicar la secuenciación y la planificación mental mediante una conversación sobre cómo prepararse para una salida familiar, sin realizar un desplazamiento físico.$c$, $c$Practicar la organización mental de una secuencia cotidiana y evocar estrategias que la persona utilizaba en salidas conocidas.$c$, array[$c$Planificación$c$, $c$Secuenciación$c$, $c$Atención$c$, $c$Lenguaje$c$, $c$Memoria autobiográfica$c$]::text[], $c$Mencionar algo necesario para salir → organizar dos pasos con ayuda → proponer una secuencia de tres o cuatro pasos → adaptar la preparación a una situación diferente.$c$, $c$No pedir a la persona que se desplace ni que demuestre habilidades de orientación en el exterior. Si la actividad despierta preocupación por salir o perderse, cambiar a un ejemplo tranquilo y familiar.$c$, array[$c$Planificación$c$, $c$secuenciación$c$, $c$atención$c$, $c$lenguaje$c$, $c$memoria autobiográfica$c$]::text[], $c$Revisión oct 2026: Confirmar que la audiencia incluye Preventivo (viñeta vacía en el documento). El «Sabías que» habla de «recordar cómo nos preparábamos» aunque la actividad es imaginar.$c$ from public.media_resources where codigo = $c$COG-005$c$
on conflict (resource_id) do update set objetivo = excluded.objetivo, objetivo_esperado = excluded.objetivo_esperado, areas_trabajo = excluded.areas_trabajo, progresion = excluded.progresion, reglas = excluded.reglas, etiquetas = excluded.etiquetas, pendientes = excluded.pendientes, updated_at = now();

update public.media_resources set titulo = $c$Una compra de antes$c$, detalle = $c$Hoy realizaremos «Una compra de antes». Vamos a conversar sobre cómo se hacían las compras en una etapa de la vida de la persona. Podemos recordar un lugar, algunos productos y cómo se organizaba la compra, sin necesidad de recordar precios exactos.$c$, perfil = $c$Deterioro cognitivo leve. · Demencia leve · Demencia Moderada$c$, materiales = $c$Fotografías o dibujos de un comercio conocido, una canasta, una lista sencilla y productos habituales de la época o comunidad de la persona. No es necesario utilizar dinero real.$c$, pasos = $c$["Preguntar dónde solía hacer las compras: pulpería, feria, mercado, supermercado u otro lugar.", "Invitar a nombrar dos o tres productos que acostumbraba comprar.", "Mostrar una lista o imágenes y pedir que elija cuáles habría incluido en una compra habitual.", "Conversar sobre cómo organizaba la compra: qué necesitaba, cómo llevaba los productos o quién le acompañaba, si desea contarlo.", "Comparar con respeto una costumbre de antes y una de ahora, sin exigir que recuerde fechas o precios."]$c$::jsonb, ayuda = null, adaptacion_por_etapa = $c${"dcl": "usar una lista breve.", "leve": "presentar dos o tres imágenes a la vez y aceptar señalar en lugar de nombrar. Evitar dinero real, operaciones complejas o situaciones que puedan generar preocupación económica.", "moderada": "presentar dos o tres imágenes a la vez y aceptar señalar en lugar de nombrar. Evitar dinero real, operaciones complejas o situaciones que puedan generar preocupación económica."}$c$::jsonb, precaucion = null, ciencia = $c${"gancho": "¿Sabías que las compras cotidianas requieren recordar productos, prestar atención y organizar información?", "evidencia": "Una revisión científica de 2023, titulada “Virtual reality applications based on instrumental activities of daily living (iADLs) for cognitive intervention in older adults: a systematic review”, analizó cómo actividades simuladas, como comprar en un supermercado, pueden utilizarse para ejercitar habilidades cognitivas.", "cierre": "Hoy vamos a recordar cómo hacíamos las compras antes, qué productos elegíamos y cómo nos organizábamos, estimulando nuestra memoria, atención y lenguaje. 🛒"}$c$::jsonb, extras = null, niveles_cognitivos = array[$c$dcl$c$, $c$leve$c$, $c$moderada$c$]::text[], duracion = $c$10–15 minutos$c$, frecuencia = $c$2–3 veces por semana$c$, orden = 6, estado_clinico = 'aprobado', adaptacion = null, por_que = null, objetivo = null, progresion = null, requisito = null, dominios = null, updated_at = now() where codigo = $c$COG-006$c$;
insert into public.media_resources_interno (resource_id, objetivo, objetivo_esperado, areas_trabajo, progresion, reglas, etiquetas)
select id, $c$Evocar una experiencia de compra cotidiana y organizar verbalmente algunos pasos, productos o decisiones habituales de esa época.$c$, $c$Facilitar la evocación de una actividad cotidiana significativa y practicar la selección y organización verbal de información familiar.$c$, array[$c$Memoria autobiográfica$c$, $c$Memoria semántica$c$, $c$Lenguaje$c$, $c$Atención$c$, $c$Secuenciación$c$]::text[], $c$Recordar el lugar → nombrar productos → seleccionar imágenes → describir uno o dos pasos de la compra → comparar una costumbre de antes y de ahora.$c$, $c$Elegir productos y comercios relacionados con la experiencia real de la persona. No evaluar cálculo, precios ni capacidad para manejar dinero; el propósito es conversar y recordar.$c$, array[$c$Memoria autobiográfica$c$, $c$memoria semántica$c$, $c$lenguaje$c$, $c$atención$c$, $c$secuenciación$c$]::text[] from public.media_resources where codigo = $c$COG-006$c$
on conflict (resource_id) do update set objetivo = excluded.objetivo, objetivo_esperado = excluded.objetivo_esperado, areas_trabajo = excluded.areas_trabajo, progresion = excluded.progresion, reglas = excluded.reglas, etiquetas = excluded.etiquetas, updated_at = now();

update public.media_resources set titulo = $c$Detectives de detalles$c$, detalle = $c$Hoy realizaremos «Detectives de detalles». Vamos a descubrir lo que tenemos alrededor, buscando objetos por su color, forma o utilidad. Podemos hacerlo desde donde estamos sentados, señalando o nombrando lo que encontramos. 🔎$c$, perfil = $c$Preventivo. · Deterioro cognitivo leve. · Demencia leve. · Demencia moderada, con consignas simples y acompañamiento cercano.$c$, materiales = $c$Objetos que estén a la vista en el lugar donde se encuentra la persona. No se necesitan fotografías, materiales impresos ni preparar un espacio especial.$c$, pasos = $c$["Observar primero el entorno y elegir una consigna que tenga respuestas visibles.", "Invitar a buscar: «¿Ve algo de color rojo?», «¿Qué objeto tiene forma redonda?» o «¿Qué sirve para sentarse?».", "Dar tiempo para mirar y permitir que responda señalando, nombrando o describiendo el objeto.", "Si necesita ayuda, orientar la búsqueda: «Miremos hacia la mesa» o «Busquemos juntos cerca de la ventana».", "Proponer otra consigna mientras mantenga el interés. No es necesario levantarse ni recoger los objetos."]$c$::jsonb, ayuda = null, adaptacion_por_etapa = $c${"preventivo": "proponer un reto como «Encuentre cinco objetos de color blanco lo más rápido que pueda» o «Busque tres objetos redondos». Comprobar primero que haya suficientes objetos visibles. Si resulta sencillo, combinar características: «Algo rojo que sirva para cocinar». La rapidez es opcional.", "dcl": "pedir dos o tres objetos con una misma característica, utilizando una consigna a la vez. Repetirla cuando sea necesario y evitar la presión de tiempo.", "leve": "buscar un objeto por ronda con indicaciones concretas: «Señale algo rojo» o «¿Qué sirve para sentarse?». Ofrecer pistas sobre dónde mirar.", "moderada": "elegir un objeto visible y cercano, reducir las distracciones y acompañar con gestos. Por ejemplo: «Busquemos la silla», señalando hacia la zona donde está. Si hace falta, mostrar dos objetos y preguntar «¿Cuál sirve para tomar agua?». Aceptar la mirada dirigida, el gesto o el señalamiento como formas de participación."}$c$::jsonb, precaucion = null, ciencia = $c${"gancho": "¿Sabías que la atención nos ayuda a encontrar detalles importantes?", "evidencia": "Una investigación publicada en 2023 encontró beneficios del entrenamiento cognitivo para la atención en personas mayores con deterioro cognitivo.", "cierre": "Hoy vamos a explorar nuestro entorno y descubrir detalles cotidianos, practicando la atención y la observación visual. 🔎"}$c$::jsonb, extras = null, niveles_cognitivos = array[$c$preventivo$c$, $c$dcl$c$, $c$leve$c$, $c$moderada$c$]::text[], duracion = $c$10–15 minutos$c$, frecuencia = $c$2–3 veces por semana$c$, orden = 7, estado_clinico = 'aprobado', adaptacion = null, por_que = null, objetivo = null, progresion = null, requisito = null, dominios = null, updated_at = now() where codigo = $c$COG-007$c$;
insert into public.media_resources_interno (resource_id, objetivo, objetivo_esperado, areas_trabajo, progresion, reglas, etiquetas, pendientes)
select id, $c$Estimular la atención selectiva y la exploración visual mediante la búsqueda de objetos del entorno, siguiendo consignas de color, forma o función.$c$, $c$Practicar la búsqueda de objetos cotidianos a partir de una consigna, ajustando la complejidad y el apoyo a las capacidades de la persona.$c$, array[$c$Atención selectiva$c$, $c$Exploración y discriminación visual$c$, $c$Comprensión verbal$c$, $c$Memoria semántica, cuando se identifica para qué sirve un objeto$c$, $c$Velocidad de procesamiento, únicamente en las variantes con reto de rapidez$c$]::text[], $c$Localizar un objeto con ayuda → encontrar un objeto sin ayuda → encontrar varios con una característica común → combinar dos características → añadir un reto de rapidez, únicamente si resulta adecuado y agradable.$c$, $c$Evitar imágenes recargadas y letras pequeñas. No medir el éxito por la rapidez; valorar la participación y ajustar la dificultad.$c$, array[$c$Atención selectiva$c$, $c$exploración visual$c$, $c$comprensión$c$, $c$velocidad de procesamiento$c$]::text[], $c$Revisión oct 2026: Las reglas dicen evitar imágenes recargadas, pero la actividad no usa imágenes.$c$ from public.media_resources where codigo = $c$COG-007$c$
on conflict (resource_id) do update set objetivo = excluded.objetivo, objetivo_esperado = excluded.objetivo_esperado, areas_trabajo = excluded.areas_trabajo, progresion = excluded.progresion, reglas = excluded.reglas, etiquetas = excluded.etiquetas, pendientes = excluded.pendientes, updated_at = now();

update public.media_resources set titulo = $c$Clasifiquemos por categorías$c$, detalle = $c$Hoy realizaremos «Clasifiquemos por categorías». Vamos a organizar algunos objetos de casa y descubrir qué tienen en común. Podemos agruparlos por su utilidad, por el lugar donde se guardan o por alguna de sus características. 🧩$c$, perfil = $c$Deterioro cognitivo leve. · Demencia leve. · Demencia moderada, con objetos familiares y acompañamiento.$c$, materiales = $c$Objetos disponibles en casa, colocados sobre una mesa: prendas de vestir, frutas, verduras o utensilios seguros, por ejemplo. Elegir objetos limpios, fáciles de reconocer y suficientemente grandes. No utilizar elementos cortantes, medicamentos, productos de limpieza ni piezas pequeñas$c$, pasos = $c$["Elegir los objetos y colocarlos al alcance de la persona, sobre una superficie despejada.", "Explicar una consigna concreta: «Vamos a poner los alimentos de este lado y la ropa de este otro».", "Mostrar un ejemplo si necesita ayuda y permitir que continúe colocando o señalando los objetos.", "Cuando termine, comentar juntos cómo quedaron los grupos. Si le resulta cómodo, preguntar: «¿Qué tienen en común?».", "Si la tarea resulta sencilla, proponer una clasificación más específica o cambiar el criterio, según las adaptaciones siguientes."]$c$::jsonb, ayuda = null, adaptacion_por_etapa = $c${"dcl": "utilizar entre ocho y doce objetos, según tolerancia. Pedir una clasificación inicial y luego cambiar la regla. Por ejemplo, agrupar prendas por tipo —camisas, pantalones y medias— y después reorganizarlas según se utilicen para clima frío o caliente. Invitar a explicar el criterio y proponer otra manera de organizarlas.", "leve": "utilizar entre seis y ocho objetos familiares. Comenzar con dos categorías y, si resulta sencillo, trabajar subcategorías: separar frutas de verduras o camisas de medias. También pueden clasificar por el lugar donde se guardan. Ofrecer una consigna a la vez y mostrar un ejemplo cuando sea necesario.", "moderada": "comenzar con cuatro objetos de dos categorías claramente diferentes, como dos prendas y dos alimentos conocidos. Decir: «La ropa va aquí y la comida va aquí», señalando cada espacio y colocando un ejemplo. Entregar un objeto a la vez si necesita más apoyo. Aceptar que señale dónde colocarlo, sin exigir que nombre la categoría ni explique su elección."}$c$::jsonb, precaucion = null, ciencia = $c${"gancho": "¿Sabías que reconocer para qué sirven los objetos y qué tienen en común utiliza nuestros conocimientos sobre el mundo?", "evidencia": "Clasificarlos permite practicar la memoria semántica y la atención. Cuando cambiamos la regla para organizarlos, también ponemos en juego la flexibilidad cognitiva.", "cierre": "Hoy vamos a organizar objetos cotidianos, reconociendo semejanzas y explorando distintas maneras de agruparlos. 🧩"}$c$::jsonb, extras = null, niveles_cognitivos = array[$c$dcl$c$, $c$leve$c$, $c$moderada$c$]::text[], duracion = $c$5–15 minutos, ajustables al interés y tolerancia.$c$, frecuencia = $c$2 veces por semana como orientación, según el plan individual.$c$, orden = 8, estado_clinico = 'aprobado', adaptacion = null, por_que = null, objetivo = null, progresion = null, requisito = null, dominios = null, updated_at = now() where codigo = $c$COG-008$c$;
insert into public.media_resources_interno (resource_id, objetivo, objetivo_esperado, areas_trabajo, progresion, reglas, etiquetas)
select id, $c$Practicar la clasificación de objetos cotidianos según sus características o utilidad, ajustando la complejidad y el acompañamiento a las capacidades de la persona.$c$, $c$Favorecer la organización de conceptos y la capacidad de reconocer semejanzas entre elementos cotidianos.$c$, array[$c$Razonamiento$c$, $c$Flexibilidad cognitiva$c$, $c$Lenguaje$c$, $c$Memoria semántica$c$, $c$Atención$c$]::text[], $c$Separar dos grupos con ayuda → clasificar sin ayuda → formar subcategorías → reorganizar los mismos objetos con otro criterio → proponer una forma diferente de agruparlos.$c$, $c$Actividad con objetos disponibles en casa; no requiere imágenes ni tarjetas. Mostrar al familiar la variante correspondiente. Ajustar cantidad de objetos, categorías y apoyo según la respuesta de la persona. Aceptar clasificaciones alternativas razonables. En demencia moderada, mantener un único criterio y evitar exigir explicaciones. Si aparece dificultad, reducir objetos y modelar un ejemplo.$c$, array[$c$Categorización$c$, $c$razonamiento$c$, $c$memoria semántica$c$, $c$atención$c$, $c$lenguaje$c$, $c$flexibilidad cognitiva$c$]::text[] from public.media_resources where codigo = $c$COG-008$c$
on conflict (resource_id) do update set objetivo = excluded.objetivo, objetivo_esperado = excluded.objetivo_esperado, areas_trabajo = excluded.areas_trabajo, progresion = excluded.progresion, reglas = excluded.reglas, etiquetas = excluded.etiquetas, updated_at = now();

update public.media_resources set titulo = $c$Un recorrido para recordar$c$, detalle = $c$Hoy realizaremos «Un recorrido para recordar». Vamos a imaginar que colocamos algunas palabras en distintos lugares de la casa. Para recordarlas, crearemos escenas divertidas y exageradas: ¡una naranja del tamaño de un sillón puede resultar difícil de olvidar!$c$, perfil = $c$Preventivo. · Deterioro cognitivo leve, cuando la persona comprenda la estrategia y pueda imaginar las asociaciones con acompañamiento.$c$, materiales = $c$No se necesitan imágenes ni tarjetas. El familiar leerá una lista breve de palabras y acompañará la creación de un recorrido imaginario por una casa conocida.$c$, pasos = $c$["Elegir dos o tres lugares de una casa que la persona conozca bien, siguiendo un orden sencillo: puerta de entrada → sala → cocina.", "Comenzar con dos o tres palabras, colocando mentalmente una en cada lugar.", "Imaginar juntos una escena llamativa que una cada palabra con su lugar. Puede tener un tamaño exagerado, movimiento o un sonido divertido.", "Repasar el recorrido y las escenas en el mismo orden.", "Invitar a recorrer nuevamente la casa en su imaginación: «¿Qué habíamos imaginado en la puerta? ¿Y en la sala?».", "Si necesita ayuda, recordar parte de la escena y reconstruirla juntos."]$c$::jsonb, ayuda = null, adaptacion_por_etapa = $c${"preventivo": "comenzar con tres palabras e invitar a crear sus propias asociaciones. Aumentar gradualmente hasta cinco, manteniendo un lugar distinto para cada palabra.", "dcl": "comenzar con dos palabras y dos lugares muy conocidos. Construir las escenas juntos, repetir el recorrido y ofrecer pistas. Aumentar la cantidad únicamente si comprende y disfruta la estrategia. Si imaginar las escenas resulta difícil, elegir otro recurso más concreto."}$c$::jsonb, precaucion = null, ciencia = $c${"gancho": "¿Sabías que relacionar información nueva con lugares conocidos puede ayudarnos a recordarla?", "evidencia": "Esta estrategia se llama método de los lugares o método de loci. Utiliza un recorrido familiar como guía para organizar la información y recuperarla después.", "cierre": "Hoy vamos a unir palabras con lugares de una casa conocida, utilizando nuestra imaginación para practicar una forma de aprender y recordar. 🏡🧠"}$c$::jsonb, extras = $c${"modo": "tabla", "titulo": "Ejemplo para practicar", "columnas": ["Lugar del recorrido", "Escena que imaginaremos"], "filas": [["Puerta de entrada", "Un pan gigante bloquea la puerta y huele a recién horneado."], ["Sala", "Un sombrero enorme salta sobre el sillón."], ["Cocina", "Una naranja del tamaño de una pelota rueda sobre la mesa."]], "intro": "Vamos a recordar estas tres palabras: pan, sombrero y naranja.", "cierre": "Después, preguntar: «Volvamos a recorrer la casa en nuestra imaginación. ¿Qué había en la entrada? ¿Qué encontramos en la sala? ¿Y en la cocina?»."}$c$::jsonb, niveles_cognitivos = array[$c$preventivo$c$, $c$dcl$c$]::text[], duracion = $c$10–15 minutos, ajustables al interés y tolerancia.$c$, frecuencia = $c$2–3 veces por semana como orientación, según el plan individual.$c$, orden = 10, estado_clinico = 'aprobado', adaptacion = null, por_que = null, objetivo = null, progresion = null, requisito = null, dominios = null, updated_at = now() where codigo = $c$COG-010$c$;
insert into public.media_resources_interno (resource_id, objetivo, objetivo_esperado, areas_trabajo, progresion, reglas, etiquetas)
select id, $c$Practicar una estrategia de memoria que consiste en asociar palabras con lugares conocidos de la casa, utilizando imágenes mentales llamativas para facilitar su recuerdo.$c$, $c$Aprender y practicar una estrategia para recordar una lista breve mediante asociaciones entre palabras, escenas imaginadas y lugares familiares.$c$, array[$c$Memoria episódica verbal$c$, $c$Aprendizaje asociativo$c$, $c$Imaginación visual$c$, $c$Organización de la información$c$, $c$Atención$c$]::text[], $c$Asociar dos palabras con dos lugares y ayuda → recordar tres asociaciones → crear sus propias escenas → ampliar hasta cuatro o cinco palabras, si maneja la estrategia con comodidad.$c$, $c$Actividad verbal e imaginativa, sin desplazamiento físico ni materiales adicionales. Mostrar las instrucciones y el ejemplo al familiar. Mantener el mismo recorrido durante cada práctica y una palabra por lugar. No cambiar ni retirar palabras mientras se está aprendiendo la estrategia. Ofrecer pistas y repasar las asociaciones cuando sea necesario. No utilizar como evaluación clínica. Simplificar o cambiar de recurso si genera confusión o frustración.$c$, array[$c$Memoria episódica$c$, $c$aprendizaje asociativo$c$, $c$estrategias de memoria$c$, $c$método de loci$c$, $c$imaginación visual$c$, $c$atención$c$]::text[] from public.media_resources where codigo = $c$COG-010$c$
on conflict (resource_id) do update set objetivo = excluded.objetivo, objetivo_esperado = excluded.objetivo_esperado, areas_trabajo = excluded.areas_trabajo, progresion = excluded.progresion, reglas = excluded.reglas, etiquetas = excluded.etiquetas, updated_at = now();

update public.media_resources set titulo = $c$¿Qué necesitamos llevar?$c$, detalle = $c$Hoy realizaremos «¿Qué necesitamos llevar?». Vamos a imaginar situaciones conocidas, como salir un día lluvioso o visitar la playa, y conversar sobre lo que nos sería útil llevar. Podemos pensar juntos y ofrecer opciones cuando haga falta. ☂️🏖️$c$, perfil = $c$Demencia leve. · Demencia moderada, con opciones concretas y acompañamiento del familiar.$c$, materiales = $c$No se necesitan materiales. La actividad se realiza mediante una conversación. Si facilita la comprensión, pueden mostrar dos objetos disponibles en casa para que la persona elija.$c$, pasos = $c$["Elegir una situación que resulte conocida para la persona.", "Hacer una pregunta breve: «Si salimos y está lloviendo, ¿qué podríamos llevar para protegernos de la lluvia?».", "Dar tiempo para responder y aceptar distintas ideas útiles.", "Si necesita ayuda, ofrecer dos opciones: «¿Una sombrilla o una toalla de baño?».", "Comentar la utilidad de su elección: «Sí, la sombrilla nos ayuda a protegernos de la lluvia».", "Continuar con otra situación mientras mantenga el interés."]$c$::jsonb, ayuda = null, adaptacion_por_etapa = $c${"leve": "comenzar con una pregunta abierta y concreta. Si responde con facilidad, invitar a mencionar otro objeto o su utilidad: «¿Qué más llevaríamos?» o «¿Para qué nos serviría?». Ofrecer opciones si lo necesita.", "moderada": "presentar una situación a la vez con una frase corta. Ofrecer dos opciones claramente diferenciadas desde el inicio si resulta necesario. Pueden mostrar objetos reales y aceptar que responda señalando, mirando o tomando el objeto. No exigir que explique su elección."}$c$::jsonb, precaucion = null, ciencia = $c${"gancho": "¿Sabías que reconocer qué objetos necesitamos utiliza nuestros conocimientos sobre su función?", "evidencia": "Relacionar una sombrilla con la lluvia o un abrigo con el frío pone en juego la memoria semántica, la comprensión del lenguaje y el razonamiento cotidiano.", "cierre": "Hoy vamos a conversar sobre situaciones conocidas y elegir objetos útiles, practicando nuestras habilidades con el apoyo que necesitemos. 💡"}$c$::jsonb, extras = $c${"modo": "tabla", "titulo": "Ejemplos para conversar", "columnas": ["Situación y pregunta", "Posibles respuestas para orientar al familiar", "Apoyo si necesita ayuda"], "filas": [["Está lloviendo y vamos a salir. ¿Qué podemos llevar para protegernos?", "Sombrilla, capa o impermeable.", "«¿Una sombrilla o una toalla de baño?»."], ["Vamos a la playa. ¿Qué podemos llevar para protegernos del sol?", "Sombrero, bloqueador solar, sombrilla o ropa que proteja del sol.", "«¿Un sombrero o una bufanda de lana?»."], ["Vamos a un lugar donde hace frío. ¿Qué ropa podríamos llevar?", "Suéter, abrigo o chaqueta.", "«¿Un abrigo o un traje de baño?»."], ["Vamos a pasar el día fuera. ¿Qué podemos llevar para tomar cuando tengamos sed?", "Agua o una bebida habitual adecuada para la persona.", "«¿Una botella de agua o un peine?»."], ["Vamos a caminar y necesitamos calzarnos. ¿Qué nos pondríamos en los pies?", "Zapatos cómodos o tenis.", "«¿Unos zapatos o unos guantes?»."], ["Vamos a comprar algunos alimentos. ¿Qué podemos llevar para traerlos?", "Bolsa, canasta o carrito de compras.", "«¿Una bolsa o una almohada?»."]]}$c$::jsonb, niveles_cognitivos = array[$c$leve$c$, $c$moderada$c$]::text[], duracion = $c$5–10 minutos, ajustables al interés y tolerancia.$c$, frecuencia = $c$2–3 veces por semana como orientación, según el plan individual.$c$, orden = 12, estado_clinico = 'aprobado', adaptacion = null, por_que = null, objetivo = null, progresion = null, requisito = null, dominios = null, updated_at = now() where codigo = $c$COG-012$c$;
insert into public.media_resources_interno (resource_id, objetivo, objetivo_esperado, areas_trabajo, progresion, reglas, etiquetas)
select id, $c$Estimular la elección de objetos útiles para situaciones cotidianas mediante preguntas sencillas y familiares.$c$, $c$Favorecer la participación en elecciones sencillas y el reconocimiento de la utilidad de objetos cotidianos, ajustando las preguntas y la ayuda a las capacidades de la persona.$c$, array[$c$Memoria semántica$c$, $c$Comprensión verbal$c$, $c$Razonamiento práctico$c$, $c$Elección entre alternativas$c$, $c$Lenguaje expresivo, cuando se responde verbalmente$c$]::text[], $c$Elegir entre dos objetos u opciones → responder sin opciones → mencionar otro objeto útil → explicar brevemente para qué lo llevaría.$c$, $c$Asignar a demencia leve y moderada según comprensión y apoyo requerido. Mostrar al familiar las situaciones, posibles respuestas y opciones de ayuda. Actividad principalmente verbal, con objetos reales como apoyo opcional. Aceptar respuestas alternativas que sean útiles para la situación. Alternar la posición de la opción adecuada al leer las alternativas. Evitar situaciones desconocidas o que generen angustia. No utilizar las respuestas para determinar si la persona puede salir sola o tomar decisiones de seguridad.$c$, array[$c$Memoria semántica$c$, $c$comprensión verbal$c$, $c$razonamiento práctico$c$, $c$elección entre alternativas$c$, $c$lenguaje$c$]::text[] from public.media_resources where codigo = $c$COG-012$c$
on conflict (resource_id) do update set objetivo = excluded.objetivo, objetivo_esperado = excluded.objetivo_esperado, areas_trabajo = excluded.areas_trabajo, progresion = excluded.progresion, reglas = excluded.reglas, etiquetas = excluded.etiquetas, updated_at = now();

update public.media_resources set titulo = $c$Completemos el refrán$c$, detalle = $c$Hoy realizaremos «Completemos el refrán». Vamos a escuchar el inicio de algunos refranes e intentar recordar cómo siguen. Si alguno no viene a la mente, podemos completarlo juntos y conversar sobre su significado.$c$, perfil = $c$Preventivo. · Deterioro cognitivo leve. · Demencia leve, con pistas verbales y guía del familiar.$c$, materiales = $c$Tarjetas digitales disponibles en la app con el inicio de diez refranes y la opción de mostrar la frase completa. No se necesitan materiales impresos.$c$, pasos = $c$["Abrir una tarjeta y leer el inicio del refrán, por ejemplo: «Al que madruga…».", "Preguntar «¿cómo seguía?» y dar tiempo para responder.", "Si necesita ayuda, ofrecer una pista, como «Dios le…», o mostrar la frase completa y leerla juntos.", "Conversar sobre su significado: «¿Qué cree que significa?» o «¿En qué situación lo usaría?».", "Si surge algún recuerdo, preguntar «¿lo había escuchado antes?» o «¿quién acostumbraba decirlo?».", "Continuar con otro refrán mientras la persona disfrute la actividad."]$c$::jsonb, ayuda = null, adaptacion_por_etapa = $c${"preventivo": "invitar a completar el refrán y proponer un ejemplo de uso.", "dcl": "ofrecer pistas verbales y hacer una pregunta a la vez.", "leve": "elegir refranes familiares, decirlos juntos y utilizar ejemplos concretos. Aceptar respuestas breves sin exigir explicaciones del significado."}$c$::jsonb, precaucion = null, ciencia = $c${"gancho": "¿Sabías que las palabras, las expresiones conocidas y sus significados forman parte de nuestra memoria semántica?", "evidencia": "Una revisión publicada en 2024 por Folia y Silva describe enfoques de intervención centrados en palabras y significados, considerando las características de cada persona.", "cierre": "Hoy vamos a completar refranes conocidos y conversar sobre lo que significan, ejercitando nuestro lenguaje y la memoria semántica. 💬📚"}$c$::jsonb, extras = $c${"modo": "tarjetas", "titulo": "Tarjetas de refranes", "columnas": ["Inicio del refrán", "Continuación", "Pregunta para conversar"], "filas": [["Al que madruga…", "Dios le ayuda.", "¿Qué cree que significa?"], ["Camarón que se duerme…", "se lo lleva la corriente.", "¿En qué situación lo usaría?"], ["Más vale maña…", "que fuerza.", "¿Puede pensar en un ejemplo?"], ["Poco a poco…", "se llena el saco.", "¿Qué quiere decir este refrán?"], ["No hay mal…", "que por bien no venga.", "¿Qué cree que significa?"], ["A caballo regalado…", "no se le mira el colmillo.", "¿Cuándo se suele decir?"], ["El que mucho abarca…", "poco aprieta.", "¿Qué consejo nos da este refrán?"], ["Más sabe el diablo por viejo…", "que por diablo.", "¿Qué significa para usted?"], ["En casa de herrero…", "cuchillo de palo.", "¿En qué situación podría utilizarse?"], ["Más vale pájaro en mano…", "que cien volando.", "¿Qué cree que quiere decir?"]]}$c$::jsonb, niveles_cognitivos = array[$c$preventivo$c$, $c$dcl$c$, $c$leve$c$]::text[], duracion = $c$5–15 minutos, según interés y tolerancia. No es necesario completar todas las tarjetas.$c$, frecuencia = $c$1–2 veces por semana como orientación, según el plan individual.$c$, orden = 13, estado_clinico = 'aprobado', adaptacion = null, por_que = null, objetivo = null, progresion = null, requisito = null, dominios = null, updated_at = now() where codigo = $c$COG-013$c$;
insert into public.media_resources_interno (resource_id, objetivo, objetivo_esperado, areas_trabajo, progresion, reglas, etiquetas, pendientes)
select id, $c$Estimular el lenguaje y la memoria semántica mediante la continuación de refranes conocidos y la conversación sobre su significado.$c$, $c$Facilitar la recuperación de expresiones familiares y la comprensión de sus significados mediante una conversación agradable y sin presión por acertar.$c$, array[$c$Lenguaje expresivo y comprensivo$c$, $c$Memoria semántica$c$, $c$Acceso a palabras y expresiones conocidas$c$, $c$Atención verbal$c$]::text[], $c$Escuchar el refrán completo → completarlo con una pista → completarlo sin ayuda → explicar su significado o mencionar una situación en la que se utiliza.$c$, $c$Recurso independiente de la actividad 04, clasificado en lenguaje. Mostrar una tarjeta a la vez con el inicio del refrán y un botón «Ver frase completa». Al desplegarla, mostrar la pregunta de conversación. Incluir botones «Anterior» y «Siguiente». La respuesta es oral, sin puntuación ni límite de tiempo. Aceptar variantes regionales y ofrecer pistas. Si un refrán no resulta familiar, pasar a otro.$c$, array[$c$Lenguaje$c$, $c$memoria semántica$c$, $c$acceso léxico$c$, $c$comprensión verbal$c$, $c$atención$c$]::text[], $c$Revisión oct 2026: La cita «Folia y Silva (2024)» parece confundir la revista Folia Phoniatrica et Logopaedica con autores.$c$ from public.media_resources where codigo = $c$COG-013$c$
on conflict (resource_id) do update set objetivo = excluded.objetivo, objetivo_esperado = excluded.objetivo_esperado, areas_trabajo = excluded.areas_trabajo, progresion = excluded.progresion, reglas = excluded.reglas, etiquetas = excluded.etiquetas, pendientes = excluded.pendientes, updated_at = now();

update public.media_resources set titulo = $c$Mi memoria tiene un plan$c$, detalle = $c$Hoy realizaremos «Mi memoria tiene un plan». Vamos a elegir algo que cuesta recordar y buscar una manera de facilitarlo. Anotar y revisar nuestros pendientes puede ayudarnos a organizarnos. 📝$c$, perfil = $c$Preventivo. · Deterioro cognitivo leve, con acompañamiento cuando sea necesario.$c$, materiales = $c$Una libreta o agenda y un lápiz. También puede utilizarse el calendario del celular si la persona lo maneja con facilidad. Elegir un solo medio para anotar los pendientes.$c$, pasos = $c$["Conversar sobre algo que se haya olvidado recientemente: «¿Hubo algo que quería hacer y se le pasó?». Elegir un solo ejemplo.", "Escribirlo en una frase corta: «Se me olvidó llamar a mi hermana».", "Anotar cuándo podría hacerlo: «Mañana, después del desayuno, llamar a mi hermana».", "Dejar la agenda en un lugar visible y acordar un momento para consultarla cada día. Por ejemplo: después del desayuno.", "Al revisar la agenda, realizar el pendiente o decidir cuándo hacerlo. Marcarlo cuando esté terminado.", "Después de unos días, conversar: «¿Nos ayudó tenerlo anotado? ¿Qué podemos cambiar para que sea más fácil?»."]$c$::jsonb, ayuda = null, adaptacion_por_etapa = $c${"preventivo": "registrar sus propios pendientes y elegir un momento diario para revisar la agenda.", "dcl": "utilizar una agenda sencilla, con letra clara y pocos pendientes por día. El familiar puede acompañar la escritura y la consulta, procurando que la persona participe."}$c$::jsonb, precaucion = null, ciencia = $c${"gancho": "¿Sabías que una agenda puede funcionar como un apoyo para la memoria?", "evidencia": "Un ensayo de Greenaway, Duncan y Smith (2013) encontró beneficios en el funcionamiento cotidiano y en la confianza para manejar dificultades de memoria después de un entrenamiento estructurado con calendario y libreta en personas con deterioro cognitivo leve amnésico.", "cierre": "Hoy vamos a practicar cómo anotar y consultar nuestros pendientes para facilitar la organización diaria. 📝"}$c$::jsonb, extras = null, niveles_cognitivos = array[$c$preventivo$c$, $c$dcl$c$]::text[], duracion = $c$5–10 minutos para preparar el sistema y unos minutos para la consulta diaria.$c$, frecuencia = $c$Consulta diaria y revisión semanal de su utilidad.$c$, orden = 14, estado_clinico = 'aprobado', adaptacion = null, por_que = null, objetivo = null, progresion = null, requisito = null, dominios = null, updated_at = now() where codigo = $c$COG-014$c$;
insert into public.media_resources_interno (resource_id, objetivo, objetivo_esperado, areas_trabajo, progresion, reglas, etiquetas)
select id, $c$Reconocer una dificultad cotidiana de memoria y practicar el uso de una agenda o libreta para organizar pendientes.$c$, $c$Establecer un hábito de registro y consulta que facilite el manejo de tareas cotidianas.$c$, array[$c$Organización$c$, $c$Planificación$c$, $c$Atención al registrar información$c$, $c$Reconocimiento de las propias necesidades de apoyo$c$, $c$Uso de estrategias para recordar pendientes$c$]::text[], $c$Anotar un pendiente con ayuda → consultar la agenda en un momento fijo → registrar y revisar pendientes con mayor autonomía → ajustar el sistema según lo que resulte útil.$c$, $c$Mostrar instrucciones y un ejemplo de pendiente. No requiere escribir información personal en la app. No pedir un registro exhaustivo de olvidos ni utilizarlos como puntuación de deterioro. Registrar también las estrategias que funcionan. Simplificar si genera preocupación o resulta difícil de mantener.$c$, array[$c$Organización$c$, $c$planificación$c$, $c$apoyos externos$c$, $c$estrategias de memoria$c$, $c$autonomía cotidiana$c$]::text[] from public.media_resources where codigo = $c$COG-014$c$
on conflict (resource_id) do update set objetivo = excluded.objetivo, objetivo_esperado = excluded.objetivo_esperado, areas_trabajo = excluded.areas_trabajo, progresion = excluded.progresion, reglas = excluded.reglas, etiquetas = excluded.etiquetas, updated_at = now();

update public.media_resources set titulo = $c$Cuando ocurra esto, haré aquello$c$, detalle = $c$Hoy realizaremos «Cuando ocurra esto, haré aquello». Vamos a practicar un truco para recordar un pendiente: unirlo con algo que hacemos todos los días. 📌$c$, perfil = $c$Preventivo. · Deterioro cognitivo leve, con una sola asociación y acompañamiento cuando sea necesario.$c$, materiales = $c$No se necesitan materiales. Puede utilizarse una nota visible como apoyo.$c$, pasos = $c$["Elegir algo sencillo que se quiera recordar. Por ejemplo: dejar listo un libro que hay que devolver.", "Elegir un momento de la rutina para hacerlo, como terminar el desayuno.", "Decir juntos la frase: «Cuando termine de desayunar, pondré el libro junto a mi bolso».", "Imaginar ese momento: terminar de desayunar, buscar el libro y colocarlo junto al bolso.", "Poner en práctica el plan la próxima vez que llegue ese momento. Si hace falta, dejar una nota visible que diga: «Poner el libro junto al bolso».", "Después, conversar sobre si el plan ayudó. Si no funcionó, elegir otro momento o añadir un recordatorio."]$c$::jsonb, ayuda = null, adaptacion_por_etapa = $c${"preventivo": "elegir una tarea, construir su propia frase y valorar qué momento de la rutina resulta más útil.", "dcl": "preparar la frase con acompañamiento. Elegir una señal evidente y una acción sencilla que pueda realizarse inmediatamente después. Practicar con un solo pendiente a la vez."}$c$::jsonb, precaucion = null, ciencia = $c${"gancho": "¿Sabías que decidir cuándo y en qué situación haremos algo puede ayudarnos a recordarlo?", "evidencia": "Esta estrategia se llama intención de implementación y consiste en unir una señal con una acción: «Cuando pase esto, haré aquello». Estudios en personas mayores han encontrado beneficios para determinadas tareas de memoria prospectiva, que es la capacidad de recordar hacer algo más adelante.", "cierre": "Hoy vamos a transformar un pendiente en un plan concreto, eligiendo cuándo lo haremos. 📌"}$c$::jsonb, extras = null, niveles_cognitivos = array[$c$preventivo$c$, $c$dcl$c$]::text[], duracion = $c$5–10 minutos para preparar el plan y una revisión breve después de ponerlo en práctica.$c$, frecuencia = $c$Practicar con un pendiente por día, según necesidad.$c$, orden = 15, estado_clinico = 'aprobado', adaptacion = null, por_que = null, objetivo = null, progresion = null, requisito = null, dominios = null, updated_at = now() where codigo = $c$COG-015$c$;
insert into public.media_resources_interno (resource_id, objetivo, objetivo_esperado, areas_trabajo, progresion, reglas, etiquetas)
select id, $c$Practicar el recuerdo de una tarea futura asociándola con un momento o una señal concreta de la rutina.$c$, $c$Practicar una estrategia que facilite recordar y realizar una tarea cotidiana en el momento previsto.$c$, array[$c$Memoria prospectiva$c$, $c$Planificación$c$, $c$Atención a señales del entorno$c$, $c$Asociación entre una situación y una acción$c$]::text[], $c$Preparar una frase con ayuda → realizar una tarea con la señal elegida y un recordatorio → utilizar la estrategia con mayor autonomía → aplicarla a otro pendiente.$c$, $c$Mostrar instrucciones y el ejemplo de la frase. Comenzar con una sola asociación entre señal y acción. Elegir tareas de bajo riesgo. Mantener las notas, alarmas y apoyos necesarios. No utilizar como sustituto de supervisión para medicación u otras tareas que impliquen seguridad.$c$, array[$c$Memoria prospectiva$c$, $c$planificación$c$, $c$estrategias de memoria$c$, $c$señales del entorno$c$, $c$rutinas$c$]::text[] from public.media_resources where codigo = $c$COG-015$c$
on conflict (resource_id) do update set objetivo = excluded.objetivo, objetivo_esperado = excluded.objetivo_esperado, areas_trabajo = excluded.areas_trabajo, progresion = excluded.progresion, reglas = excluded.reglas, etiquetas = excluded.etiquetas, updated_at = now();

update public.media_resources set titulo = $c$Lo recuerdo después$c$, detalle = $c$Hoy realizaremos «Lo recuerdo después». Vamos a practicar cómo recordar un dato nuevo, haciendo pequeñas pausas. El familiar acompañará la actividad y ofrecerá ayuda cuando sea necesario. 🧠$c$, perfil = $c$Preventivo. · Deterioro cognitivo leve, con acompañamiento y pausas ajustadas a su respuesta.$c$, materiales = $c$Un dato breve que la persona quiera aprender y un reloj o temporizador opcional.$c$, pasos = $c$["Elegir un dato útil, como el nombre de una persona nueva: Elena.", "Decir el dato y repetirlo juntos: «La persona se llama Elena».", "Conversar de otra cosa durante unos 30 segundos. Después preguntar: «¿Cómo se llama la persona?».", "Si lo recuerda con facilidad, esperar un minuto antes de volver a preguntar. Después pueden probar con dos minutos. Durante las pausas, continuar conversando.", "Si no lo recuerda, dar la respuesta con naturalidad: «Se llama Elena. Digámoslo juntos: Elena». Volver a preguntar después de una pausa más corta.", "Terminar después de unos pocos intentos, repasando juntos el dato."]$c$::jsonb, ayuda = null, adaptacion_por_etapa = $c${"preventivo": "elegir un dato nuevo y aumentar las pausas gradualmente, siempre que lo recuerde con comodidad.", "dcl": "comenzar con repetición inmediata y pausas de pocos segundos si hace falta. Trabajar un solo dato. Cuando no lo recuerde, proporcionar la respuesta y practicar nuevamente con una pausa más corta."}$c$::jsonb, precaucion = null, ciencia = $c${"gancho": "¿Sabías que practicar el recuerdo en distintos momentos es una estrategia de aprendizaje?", "evidencia": "La recuperación espaciada consiste en intentar recordar una información después de pequeñas pausas, ajustando el tiempo según la respuesta. Esta estrategia se ha investigado en personas con deterioro cognitivo leve, incluyendo un ensayo aleatorizado del programa digital USMART publicado en 2017.", "cierre": "Hoy vamos a practicar un dato útil en pequeños pasos, con el tiempo y la ayuda que necesitemos. 🧠"}$c$::jsonb, extras = $c${"modo": "temporizador", "titulo": "Temporizador (opcional)", "segundos": [30, 60, 120]}$c$::jsonb, niveles_cognitivos = array[$c$preventivo$c$, $c$dcl$c$]::text[], duracion = $c$5–10 minutos.$c$, frecuencia = $c$2–3 veces por semana como orientación, retomando el mismo dato mientras sea útil.$c$, orden = 16, estado_clinico = 'aprobado', adaptacion = null, por_que = null, objetivo = null, progresion = null, requisito = null, dominios = null, updated_at = now() where codigo = $c$COG-016$c$;
insert into public.media_resources_interno (resource_id, objetivo, objetivo_esperado, areas_trabajo, progresion, reglas, etiquetas)
select id, $c$Practicar el aprendizaje de un dato útil mediante intentos de recuerdo separados por pausas breves y ajustadas a la persona.$c$, $c$Favorecer el aprendizaje de un dato concreto mediante práctica distribuida y ayuda adaptada.$c$, array[$c$Aprendizaje de información nueva$c$, $c$Memoria episódica$c$, $c$Recuperación de información$c$, $c$Atención$c$]::text[], $c$Repetir el dato juntos → recordarlo después de unos segundos → ampliar poco a poco la pausa → practicar el mismo dato en otra ocasión.$c$, $c$Mostrar instrucciones y ejemplo al familiar. Los intervalos son orientativos: no es necesario llegar a dos minutos. Ampliar la pausa solo cuando el recuerdo sea cómodo. Ante dificultad, dar la respuesta y acortar el intervalo. No mostrar puntuaciones ni interpretar el desempeño como evaluación clínica. Finalizar si aparece cansancio o incomodidad.$c$, array[$c$Aprendizaje$c$, $c$memoria episódica$c$, $c$recuperación espaciada$c$, $c$atención$c$, $c$estrategias de memoria$c$]::text[] from public.media_resources where codigo = $c$COG-016$c$
on conflict (resource_id) do update set objetivo = excluded.objetivo, objetivo_esperado = excluded.objetivo_esperado, areas_trabajo = excluded.areas_trabajo, progresion = excluded.progresion, reglas = excluded.reglas, etiquetas = excluded.etiquetas, updated_at = now();

update public.media_resources set titulo = $c$Un lugar para mis cosas$c$, detalle = $c$Hoy realizaremos «Un lugar para mis cosas». Vamos a elegir un lugar fijo para un objeto que la persona utilice con frecuencia y practicar juntos cómo guardarlo y encontrarlo. Pueden comenzar con los lentes o el control remoto. 🏡$c$, perfil = $c$Preventivo. · Deterioro cognitivo leve. · Demencia leve, con indicaciones breves y apoyos. · Demencia moderada, con acompañamiento directo. · Demencia severa, únicamente en la versión de participación guiada, sin exigir recuerdo posterior.$c$, materiales = $c$Un objeto cotidiano y seguro, como los lentes, su estuche o el control remoto. Una bandeja o recipiente fácil de identificar. Opcionalmente, una fotografía del objeto para señalar dónde guardarlo.$c$, pasos = $c$["Elijan un objeto que la persona utilice habitualmente.", "Acuerden un lugar visible, accesible y cercano a donde suele usarlo. Coloquen una bandeja para identificar ese espacio.", "Muestren la acción mientras dicen: «Vamos a guardar los lentes en esta bandeja».", "Inviten a la persona a colocar el objeto. Si puede, pídanle que acompañe la acción con una frase: «Mis lentes quedan en la bandeja».", "Después de una conversación breve, invítenla a buscarlo: «Vamos a buscar los lentes». Si necesita ayuda, señalen la bandeja o acompáñenla hasta el lugar.", "Al terminar de usarlo, guárdenlo nuevamente en el mismo sitio. Practiquen esta rutina en los momentos habituales del día."]$c$::jsonb, ayuda = $c$Ofrezcan una indicación concreta: «Mire, aquí está la bandeja de los lentes». Si hace falta, muestren nuevamente la acción y háganla juntos. No es necesario que recuerde la ubicación sin ayuda para poder participar.$c$, adaptacion_por_etapa = $c${"preventivo": "permitir que la persona elija el lugar y explique por qué le resulta práctico. Practicar la rutina y, posteriormente, incorporar otro objeto si lo desea.", "dcl": "trabajar con un objeto por vez. Utilizar una señal visible y acompañar la acción con una frase breve. Mantener la misma ubicación entre prácticas.", "leve": "mostrar primero qué hacer y dar una indicación por vez. Señalar el lugar cuando sea necesario y acompañar la búsqueda sin hacer preguntas repetidas para comprobar si recuerda.", "moderada": "presentar un objeto y la bandeja a la vista. Decir: «Pongamos el control aquí», acompañando con un gesto. El familiar participa durante toda la actividad.", "avanzada": "invitar a participar en una acción breve, como colocar juntos un objeto en la bandeja. Aceptar que participe mirando, tocando o acompañando el movimiento voluntariamente. Omitir la búsqueda posterior y las preguntas de recuerdo."}$c$::jsonb, precaucion = $c$No esconder el objeto ni cambiarlo de lugar para aumentar la dificultad. Evitar medicamentos, dinero, documentos importantes u objetos peligrosos. Todos los familiares deben respetar la ubicación elegida. Si aparecen frustración, cansancio o rechazo, ofrecer ayuda, simplificar o terminar la actividad.$c$, ciencia = $c${"gancho": "¿Sabías que practicar una tarea cotidiana con apoyos puede ayudar a realizarla con mayor facilidad?", "evidencia": "Una revisión Cochrane de 2023 encontró que la rehabilitación cognitiva personalizada puede mejorar el desempeño en las actividades específicamente trabajadas en personas con demencia leve o moderada.", "cierre": "Inspirándonos en este enfoque, hoy vamos a practicar una rutina concreta: guardar un objeto en el mismo lugar y utilizar las ayudas que necesitemos para encontrarlo. 🧠"}$c$::jsonb, extras = null, niveles_cognitivos = array[$c$preventivo$c$, $c$dcl$c$, $c$leve$c$, $c$moderada$c$, $c$avanzada$c$]::text[], duracion = $c$De 5 a 10 minutos. En demencia moderada o severa, realizar una práctica más breve según disposición y tolerancia.$c$, frecuencia = $c$Practicar en los momentos habituales de uso del objeto, sin repetir innecesariamente.$c$, orden = 17, estado_clinico = 'aprobado', adaptacion = null, por_que = null, objetivo = null, progresion = null, requisito = null, dominios = null, updated_at = now() where codigo = $c$COG-017$c$;
insert into public.media_resources_interno (resource_id, objetivo, objetivo_esperado, areas_trabajo, progresion, reglas, etiquetas)
select id, $c$Practicar una rutina para guardar y localizar un objeto cotidiano mediante una ubicación fija y apoyos visuales o verbales.$c$, $c$Facilitar que la persona participe en guardar y localizar un objeto cotidiano en un lugar fijo, con los apoyos que necesite. En demencia severa, favorecer la participación acompañada en la acción de guardar, sin exigir aprendizaje de la ubicación.$c$, array[$c$Atención$c$, $c$Asociación entre un objeto y su ubicación$c$, $c$Aprendizaje de una rutina cotidiana$c$, $c$Uso de apoyos externos para la memoria$c$, $c$Participación funcional$c$]::text[], $c$Guardar un objeto con demostración → guardarlo con una indicación → localizarlo utilizando la señal visual → practicar la rutina con menos ayuda, si resulta posible.
Incorporar un segundo objeto únicamente cuando la primera rutina resulte familiar. Mantener las señales que sigan siendo útiles.$c$, $c$Elegir la adaptación según las capacidades actuales. Mantener un objeto y una ubicación al inicio. En demencia moderada y severa, acompañamiento directo. En severa, omitir la búsqueda y la exigencia de recuerdo.$c$, array[$c$Memoria cotidiana$c$, $c$atención$c$, $c$asociación$c$, $c$rutinas$c$, $c$apoyos externos$c$, $c$participación funcional. La duración y frecuencia son orientaciones prácticas. Esta actividad es una adaptación domiciliaria; no constituye un protocolo validado de manera independiente$c$]::text[] from public.media_resources where codigo = $c$COG-017$c$
on conflict (resource_id) do update set objetivo = excluded.objetivo, objetivo_esperado = excluded.objetivo_esperado, areas_trabajo = excluded.areas_trabajo, progresion = excluded.progresion, reglas = excluded.reglas, etiquetas = excluded.etiquetas, updated_at = now();

update public.media_resources set titulo = $c$Recordamos una noticia breve$c$, detalle = $c$Hoy realizaremos «Recordamos una noticia breve». Vamos a compartir una información interesante y conversar sobre sus ideas principales. Elijan un tema que la persona disfrute. 📰$c$, perfil = $c$Preventivo. · Deterioro cognitivo leve. · Demencia leve, con información breve y apoyos. · Demencia moderada, mediante una versión simplificada de comprensión inmediata.$c$, materiales = $c$Una noticia positiva o un texto breve sobre un tema que le interese a la persona: naturaleza, deportes, cultura o acontecimientos de su comunidad. Puede leerse en papel o contarse oralmente.$c$, pasos = $c$["Elijan un texto de tres o cuatro frases, con una idea principal clara.", "Expliquen el tema antes de comenzar: «Voy a leerle una noticia sobre un jardín de mariposas».", "Lean despacio y hagan una pausa al terminar.", "Inviten a comentar: «¿De qué trataba?» o «¿Qué le llamó la atención?».", "Si necesita ayuda, aporten una pista: «Hablaba de un lugar donde viven…».", "Vuelvan a leer la información si lo desea y reconstruyan juntos la idea principal."]$c$::jsonb, ayuda = $c$Ofrezcan dos opciones relacionadas con el contenido: «¿La noticia hablaba de mariposas o de peces?». También pueden decir una parte y permitir que complete: «En el jardín había muchas…».$c$, adaptacion_por_etapa = $c${"preventivo": "utilizar textos algo más extensos y pedir que explique la noticia con sus propias palabras.", "dcl": "trabajar con tres o cuatro frases y recuperar primero la idea principal. Permitir releer.", "leve": "presentar una o dos frases, acompañadas de una imagen si resulta útil. Ofrecer preguntas concretas y opciones.", "moderada": "compartir una sola frase sobre algo visible o familiar y comentarla inmediatamente. Omitir el recuerdo después de una pausa.", "avanzada": "no utilizar esta actividad en su formato de comprensión y recuerdo de noticias."}$c$::jsonb, precaucion = $c$Evitar noticias alarmantes, violentas o que generen preocupación. No exigir fechas, nombres o detalles secundarios. Verificar que la persona escuche y comprenda la lectura.$c$, ciencia = $c${"gancho": "Compartir información y conversar sobre ella permite combinar comprensión, atención y memoria en una interacción significativa. Los programas de estimulación cognitiva incluyen conversaciones y actividades variadas.", "evidencia": "", "cierre": "Hoy vamos a escuchar, comprender y comentar una información que nos interese."}$c$::jsonb, extras = null, niveles_cognitivos = array[$c$preventivo$c$, $c$dcl$c$, $c$leve$c$, $c$moderada$c$]::text[], duracion = $c$De 5 a 10 minutos; reducir en demencia moderada.$c$, frecuencia = $c$De 2 a 3 veces por semana, variando los temas.$c$, orden = 18, estado_clinico = 'aprobado', adaptacion = null, por_que = null, objetivo = null, progresion = null, requisito = null, dominios = null, updated_at = now() where codigo = $c$COG-018$c$;
insert into public.media_resources_interno (resource_id, objetivo, objetivo_esperado, areas_trabajo, progresion, reglas, etiquetas)
select id, $c$Practicar la comprensión y el recuerdo de información breve mediante una conversación sobre un tema de interés.$c$, $c$Facilitar que la persona identifique o reconstruya la idea principal de una información breve, con la ayuda necesaria.$c$, array[$c$Comprensión verbal$c$, $c$Atención auditiva$c$, $c$Memoria de información reciente$c$, $c$Organización de ideas$c$, $c$Expresión oral$c$]::text[], $c$Comprender una frase → comentar la idea principal de un texto breve → recordar algún detalle → retomar la información después de una conversación corta.$c$, $c$Elegir un tema de interés. Ajustar la extensión y permitir repetición. En demencia moderada, trabajar comprensión inmediata.$c$, array[$c$Memoria reciente$c$, $c$comprensión verbal$c$, $c$atención auditiva$c$, $c$conversación$c$]::text[] from public.media_resources where codigo = $c$COG-018$c$
on conflict (resource_id) do update set objetivo = excluded.objetivo, objetivo_esperado = excluded.objetivo_esperado, areas_trabajo = excluded.areas_trabajo, progresion = excluded.progresion, reglas = excluded.reglas, etiquetas = excluded.etiquetas, updated_at = now();

update public.media_resources set titulo = $c$La historia de dos objetos$c$, detalle = $c$Hoy realizaremos «La historia de dos objetos». Vamos a unir dos objetos mediante una frase sencilla. Podemos inventar una situación cotidiana o una historia divertida. ☕📖$c$, perfil = $c$Preventivo. · Deterioro cognitivo leve. · Demencia leve, con modelado y objetos visibles.$c$, materiales = $c$De dos a cuatro objetos cotidianos seguros, como una taza, una cuchara, un sombrero o un libro.$c$, pasos = $c$["Coloquen dos objetos sobre la mesa, por ejemplo una taza y un libro.", "Observen y nombren cada uno. Si no aparece el nombre, proporciónenlo con naturalidad.", "Propongan una frase que los relacione: «Me tomo un café mientras leo el libro».", "Inviten a la persona a repetir la idea con sus propias palabras o a proponer otra.", "Mantengan los objetos visibles y conversen brevemente sobre la escena.", "Si resulta cómodo, cubran uno y utilicen la frase como pista para recordarlo. Si no lo recuerda, muéstrenlo y reconstruyan juntos la relación."]$c$::jsonb, ayuda = $c$Comiencen la frase: «Para revolver el café de la taza utilizo una…». Acepten una palabra, un gesto o el señalamiento del objeto.$c$, adaptacion_por_etapa = $c${"preventivo": "crear asociaciones propias e incorporar un tercer objeto. Puede imaginar la escena si le resulta natural.", "dcl": "trabajar con dos objetos y una relación concreta. Repetir la misma asociación antes de cambiarla.", "leve": "el familiar propone una frase breve y la persona completa, señala o representa la acción. Mantener los objetos visibles si cubrirlos genera dificultad.", "moderada": "no utilizar la versión de aprendizaje asociativo y recuerdo. Para estos niveles, elegir actividades de reconocimiento y uso acompañado de objetos.", "avanzada": "no utilizar la versión de aprendizaje asociativo y recuerdo. Para estos niveles, elegir actividades de reconocimiento y uso acompañado de objetos."}$c$::jsonb, precaucion = $c$No insistir en crear imágenes mentales si le resulta difícil. Evitar asociaciones demasiado abstractas y objetos pequeños o peligrosos.$c$, ciencia = $c${"gancho": "¿Sabías que relacionar algo nuevo con algo conocido puede ayudarnos a recordarlo?", "evidencia": "Al unir dos objetos mediante una frase, les damos un significado que puede servirnos de pista para recordar después.", "cierre": "Hoy vamos a practicar esta estrategia con objetos de la casa. Es una forma sencilla de aprender a crear conexiones que también podemos utilizar en nuestra memoria cotidiana. 🧠"}$c$::jsonb, extras = null, niveles_cognitivos = array[$c$preventivo$c$, $c$dcl$c$, $c$leve$c$]::text[], duracion = $c$De 5 a 10 minutos.$c$, frecuencia = $c$De 2 a 3 veces por semana.$c$, orden = 19, estado_clinico = 'aprobado', adaptacion = null, por_que = null, objetivo = null, progresion = null, requisito = null, dominios = null, updated_at = now() where codigo = $c$COG-019$c$;
insert into public.media_resources_interno (resource_id, objetivo, objetivo_esperado, areas_trabajo, progresion, reglas, etiquetas)
select id, $c$Practicar la asociación de información mediante una frase que relacione dos objetos cotidianos.$c$, $c$Facilitar que la persona establezca una relación entre dos objetos y la utilice como apoyo durante la actividad.$c$, array[$c$Asociación semántica$c$, $c$Aprendizaje de información$c$, $c$Lenguaje$c$, $c$Atención$c$, $c$Imaginación, cuando resulte accesible$c$]::text[], $c$Relacionar dos objetos visibles → crear una frase propia → recordar un objeto con ayuda de la frase → enlazar tres objetos, si resulta sencillo.$c$, $c$Comenzar con dos objetos y una relación concreta. En demencia leve, priorizar el apoyo visible y el modelado.$c$, array[$c$Memoria$c$, $c$asociación$c$, $c$lenguaje$c$, $c$aprendizaje$c$, $c$objetos cotidianos. Atención$c$]::text[] from public.media_resources where codigo = $c$COG-019$c$
on conflict (resource_id) do update set objetivo = excluded.objetivo, objetivo_esperado = excluded.objetivo_esperado, areas_trabajo = excluded.areas_trabajo, progresion = excluded.progresion, reglas = excluded.reglas, etiquetas = excluded.etiquetas, updated_at = now();

update public.media_resources set titulo = $c$Escuchemos una palabra especial$c$, detalle = $c$Hoy realizaremos «Escuchemos una palabra especial». Vamos a escuchar un texto corto y hacer una señal cuando aparezca la palabra elegida. Pueden señalar un objeto, levantar un dedo o decir «aquí». 👂$c$, perfil = $c$Preventivo. · Deterioro cognitivo leve. · Demencia leve, si comprende y mantiene una regla sencilla. · Demencia moderada, únicamente en la versión de palabra y objeto visible.$c$, materiales = $c$Un texto breve preparado por el familiar y un objeto que represente la palabra elegida, si se necesita apoyo. Ejemplo: elegir la palabra «café» y leer: «En la mañana preparé café. Abrí la ventana y puse la mesa. El café estaba listo».$c$, pasos = $c$["Elijan una palabra familiar que aparezca dos o tres veces en el texto.", "Acuerden una respuesta cómoda: «Cuando escuche “café”, señale esta taza».", "Hagan un ensayo con una frase corta.", "Lean lentamente, con pausas naturales.", "Si la persona pierde la regla, recuérdenla y vuelvan a practicar juntos.", "Terminen comentando el contenido, sin contabilizar errores."]$c$::jsonb, ayuda = $c$Dejen el objeto visible y hagan la señal junto con la persona. Reduzcan el texto a una frase por vez.$c$, adaptacion_por_etapa = $c${"preventivo": "ampliar gradualmente el texto o elegir una categoría, como nombres de frutas, si la primera versión resulta fácil.", "dcl": "mantener una sola palabra y una señal visible.", "leve": "utilizar frases cortas y recordar la regla antes de cada una cuando sea necesario.", "moderada": "mostrar el objeto y decir una frase que lo incluya: «Aquí está la taza». Invitar a mirarlo o señalarlo. No exigir que mantenga una regla durante un relato.", "avanzada": "no utilizar esta actividad como detección de palabras."}$c$::jsonb, precaucion = $c$Realizar en un ambiente tranquilo y comprobar que escuche adecuadamente. Evitar sonidos fuertes, respuestas rápidas obligatorias o palmadas si producen dolor o sobresalto.$c$, ciencia = $c${"gancho": "¿Sabías que la atención nos ayuda a identificar lo que nos interesa entre todo lo que escuchamos?", "evidencia": "La utilizamos, por ejemplo, cuando seguimos una conversación aunque haya otros sonidos alrededor. Hoy vamos a practicar esta habilidad escuchando una palabra especial dentro de un relato y haciendo una señal cada vez que aparezca. Una manera sencilla de ejercitar la escucha y la concentración. 👂🧠 Un ejemplo para practicar Lean el siguiente párrafo en voz alta, a un ritmo natural y sin destacar la palabra elegida. Cada vez que la persona escuche «café», deberá hacer la señal que acordaron: levantar un dedo, señalar una taza o decir «aquí». “El domingo por la mañana, Elena decidió preparar café antes de que llegara su familia. Mientras el agua se calentaba, abrió las ventanas y acomodó unas flores en el centro de la mesa. Había comprado pan en la panadería del barrio y tenía lista una bandeja con frutas. Al poco rato llegó su hermana, quien comentó que el aroma del café se sentía desde la entrada. Las dos conversaron sobre una vecina que había comenzado a cultivar tomates en su jardín. Después llegaron los nietos, dejaron sus abrigos en una silla y salieron al patio a buscar al perro. Elena sirvió el café y se sentó junto a la ventana para escuchar las historias de la semana. Su hermana contó que había encontrado unas fotografías antiguas mientras ordenaba un armario. Todos se acercaron a mirarlas y reconocieron la casa donde pasaban las vacaciones. Entre recuerdos y risas, alguien preguntó si todavía quedaba café. Elena señaló la jarra y siguió contando la historia de aquella tarde en que una fuerte lluvia los había dejado sin electricidad”. Cómo crear sus propios párrafos", "cierre": "Elijan una palabra conocida, como «pan», «perro» o «jardín», e inclúyanla varias veces en una historia. Intercalen frases que no la contengan y eviten colocarla siempre en posiciones predecibles. Pueden inspirarse en situaciones cotidianas o temas que la persona disfrute."}$c$::jsonb, extras = null, niveles_cognitivos = array[$c$preventivo$c$, $c$dcl$c$, $c$leve$c$, $c$moderada$c$]::text[], duracion = $c$De 3 a 8 minutos.$c$, frecuencia = $c$De 2 a 3 veces por semana.$c$, orden = 20, estado_clinico = 'aprobado', adaptacion = null, por_que = null, objetivo = null, progresion = null, requisito = null, dominios = null, updated_at = now() where codigo = $c$COG-020$c$;
insert into public.media_resources_interno (resource_id, objetivo, objetivo_esperado, areas_trabajo, progresion, reglas, etiquetas)
select id, $c$Practicar la atención auditiva y la identificación de una palabra dentro de una lectura breve.$c$, $c$Facilitar que la persona identifique la palabra acordada durante una lectura breve, con apoyos cuando sean necesarios.$c$, array[$c$Atención auditiva selectiva$c$, $c$Atención sostenida$c$, $c$Comprensión de instrucciones$c$, $c$Mantenimiento de una regla sencilla$c$]::text[], $c$Identificar la palabra en una frase → mantener la regla durante varias frases → escuchar un texto un poco más largo.$c$, $c$Una palabra y una respuesta al inicio. No puntuar ni exigir velocidad. En demencia moderada, utilizar la versión inmediata con objeto visible.$c$, array[$c$Atención auditiva$c$, $c$escucha$c$, $c$comprensión$c$, $c$identificación de palabras$c$]::text[] from public.media_resources where codigo = $c$COG-020$c$
