update public.media_resources set titulo = $c$Preparemos la mesa juntos$c$, detalle = $c$Hoy realizaremos «Preparemos la mesa juntos». Vamos a organizar algunos objetos para compartir una tarea del hogar. Cada persona puede participar haciendo una parte. 🍽️$c$, perfil = $c$Demencia leve. · Demencia moderada, con instrucciones de un paso. · Demencia severa, mediante una acción acompañada y voluntaria.$c$, materiales = $c$Mantel individual, servilleta, cuchara y vaso plástico vacío. Utilizar únicamente elementos seguros.$c$, pasos = $c$["Coloquen sobre una mesa los objetos que van a utilizar.", "Expliquen: «Vamos a preparar este espacio para la merienda».", "Inviten a elegir un elemento: «Busquemos la servilleta».", "Pidan colocarlo en un lugar concreto, señalando si hace falta.", "Continúen con los demás objetos, uno por uno.", "Revisen juntos lo preparado y agradezcan su colaboración."]$c$::jsonb, ayuda = $c$Muestren el objeto y el lugar: «Esta servilleta va aquí». Pueden preparar un puesto como modelo para que la persona lo observe.$c$, adaptacion_por_etapa = $c${"leve": "entregar una indicación por vez y señalar dónde colocar cada elemento.", "moderada": "ofrecer directamente el objeto y una instrucción breve: «Ponga la servilleta aquí».", "avanzada": "invitar a una sola acción, como dejar una servilleta sobre la mesa, si puede y desea hacerlo. Aceptar otras formas de participación sin forzar el movimiento."}$c$::jsonb, precaucion = $c$Realizar sentado si es más seguro. Evitar cuchillos, vidrio, bebidas calientes y alimentos durante el ejercicio si no se han considerado las necesidades de alimentación y deglución.$c$, ciencia = $c${"gancho": "¿Sabías que preparar la mesa pone en juego varias habilidades al mismo tiempo?", "evidencia": "Buscar la servilleta, elegir los utensilios y decidir dónde colocarlos nos permite utilizar la atención, comprender indicaciones y organizar el espacio.", "cierre": "Hoy vamos a aprovechar esta tarea cotidiana para ejercitar estas habilidades y compartir un momento en familia. Cada persona puede colaborar a su manera, con la ayuda que necesite. 🍽️🧠"}$c$::jsonb, extras = null, niveles_cognitivos = array[$c$leve$c$, $c$moderada$c$, $c$avanzada$c$]::text[], duracion = $c$De 5 a 10 minutos; reducir a una interacción breve en demencia severa.$c$, frecuencia = $c$Integrar en una rutina habitual, según disposición.$c$, orden = 21, estado_clinico = 'aprobado', adaptacion = null, por_que = null, objetivo = null, progresion = null, requisito = null, dominios = null, updated_at = now() where codigo = $c$COG-021$c$;
insert into public.media_resources_interno (resource_id, objetivo, objetivo_esperado, areas_trabajo, progresion, reglas, etiquetas)
select id, $c$Practicar la atención durante una tarea cotidiana mediante la selección y colocación de objetos.$c$, $c$Favorecer que la persona complete una parte de la preparación de la mesa con el apoyo adecuado.$c$, array[$c$Atención dirigida$c$, $c$Comprensión de instrucciones$c$, $c$Reconocimiento de objetos$c$, $c$Organización espacial$c$, $c$Participación funcional$c$]::text[], $c$Colocar un objeto con demostración → seguir una indicación → completar un puesto → preparar dos puestos utilizando un modelo.$c$, $c$Objetos seguros, instrucciones breves y acompañamiento según necesidad. En demencia severa, priorizar participación voluntaria.$c$, array[$c$Atención$c$, $c$actividad cotidiana$c$, $c$organización$c$, $c$comprensión$c$, $c$participación funcional. Lenguaje$c$]::text[] from public.media_resources where codigo = $c$COG-021$c$
on conflict (resource_id) do update set objetivo = excluded.objetivo, objetivo_esperado = excluded.objetivo_esperado, areas_trabajo = excluded.areas_trabajo, progresion = excluded.progresion, reglas = excluded.reglas, etiquetas = excluded.etiquetas, updated_at = now();

update public.media_resources set titulo = $c$Describamos sin decir el nombre$c$, detalle = $c$Hoy realizaremos «Describamos sin decir el nombre». Vamos a dar pistas sobre objetos conocidos. Podemos contar para qué sirven, cómo son o dónde los utilizamos. 🗣️$c$, perfil = $c$Preventivo. · Deterioro cognitivo leve. · Demencia leve. · Demencia moderada, con objetos visibles y preguntas concretas.$c$, materiales = $c$De tres a cinco objetos cotidianos seguros o fotografías claras: peine, taza, zapato, sombrero o cuchara.$c$, pasos = $c$["El familiar comienza con un ejemplo: «Sirve para peinarse y puede tener un mango».", "Inviten a la persona a nombrar o señalar el objeto.", "Muestren otro y propongan describirlo: «¿Para qué lo usamos?» o «¿Cómo es?».", "Si resulta cómodo, alternen los turnos para dar y escuchar pistas.", "Cuando no aparezca una palabra, acepten una descripción o un gesto y aporten el nombre con naturalidad."]$c$::jsonb, ayuda = $c$Ofrezcan una frase para completar: «La cuchara sirve para…». También pueden presentar dos objetos y pedir que señale el que corresponde a la descripción.$c$, adaptacion_por_etapa = $c${"preventivo": "describir sin decir el nombre y utilizar pistas más variadas.", "dcl": "mantener el objeto visible y orientar con preguntas sobre su función, forma o lugar de uso.", "leve": "trabajar con objetos muy familiares y aceptar frases breves, gestos o señalamiento.", "moderada": "presentar uno o dos objetos y preguntar por una función concreta: «¿Cuál usamos para peinarnos?».", "avanzada": "no utilizar el juego de adivinación. Elegir una propuesta de comunicación acompañada con objetos familiares."}$c$::jsonb, precaucion = $c$Evitar que se convierta en una prueba de vocabulario. No insistir en obtener el nombre exacto si la persona logra comunicar el significado.$c$, ciencia = $c${"gancho": "¿Sabías que podemos explicar qué es un objeto aunque no nos salga su nombre?", "evidencia": "Al describir para qué sirve, cómo es o dónde lo usamos, ponemos en práctica nuestros conocimientos y buscamos otras maneras de comunicar lo que queremos decir.", "cierre": "Hoy vamos a jugar con estas pistas para ejercitar el lenguaje. Porque describir, señalar o hacer un gesto también nos ayuda a expresar una idea y mantener la conversación. 🗣️🧠"}$c$::jsonb, extras = null, niveles_cognitivos = array[$c$preventivo$c$, $c$dcl$c$, $c$leve$c$, $c$moderada$c$]::text[], duracion = $c$De 5 a 10 minutos.$c$, frecuencia = $c$De 2 a 3 veces por semana.$c$, orden = 22, estado_clinico = 'aprobado', adaptacion = null, por_que = null, objetivo = null, progresion = null, requisito = null, dominios = null, updated_at = now() where codigo = $c$COG-022$c$;
insert into public.media_resources_interno (resource_id, objetivo, objetivo_esperado, areas_trabajo, progresion, reglas, etiquetas)
select id, $c$Practicar la descripción de objetos mediante sus características, usos y relaciones.$c$, $c$Facilitar que la persona comunique una característica o función de un objeto, utilizando palabras, gestos o señalamiento.$c$, array[$c$Memoria semántica$c$, $c$Acceso a palabras$c$, $c$Descripción$c$, $c$Comprensión verbal$c$, $c$Comunicación mediante gestos y palabras$c$]::text[], $c$Reconocer un objeto por su uso → describir una característica → dar varias pistas → describir sin tenerlo a la vista, si resulta accesible.$c$, $c$Aceptar diferentes formas de respuesta. Ajustar la cantidad de objetos y ofrecer modelos.$c$, array[$c$Lenguaje$c$, $c$semántica$c$, $c$descripción$c$, $c$comprensión$c$, $c$comunicación$c$]::text[] from public.media_resources where codigo = $c$COG-022$c$
on conflict (resource_id) do update set objetivo = excluded.objetivo, objetivo_esperado = excluded.objetivo_esperado, areas_trabajo = excluded.areas_trabajo, progresion = excluded.progresion, reglas = excluded.reglas, etiquetas = excluded.etiquetas, updated_at = now();

update public.media_resources set titulo = $c$Elijamos y conversemos$c$, detalle = $c$Hoy realizaremos «Elijamos y conversemos». Vamos a ofrecer opciones y dar espacio para expresar lo que cada persona prefiere. Se puede responder hablando, señalando, mirando o haciendo un gesto. 💬$c$, perfil = $c$Demencia leve. · Demencia moderada, con opciones visibles. · Demencia severa, si puede expresar aceptación, rechazo o elección mediante una respuesta reconocible.$c$, materiales = $c$Dos objetos, fotografías o alternativas reales: dos prendas, dos canciones o dos actividades posibles.$c$, pasos = $c$["Elijan una decisión sencilla que pueda respetarse, como qué música escuchar.", "Presenten las dos opciones: «¿Prefiere escuchar esta canción o esta otra?».", "Den tiempo para responder, evitando repetir enseguida la pregunta.", "Confirmen la elección: «Entiendo que prefiere esta. ¿La escuchamos?».", "Si puede y desea conversar, pregunten qué le gusta de esa opción.", "Realicen la actividad elegida cuando sea posible."]$c$::jsonb, ayuda = $c$Presenten una opción por vez y observen la respuesta. Si no es clara, no supongan una preferencia: vuelvan a ofrecerla de forma sencilla o prueben en otro momento.$c$, adaptacion_por_etapa = $c${"leve": "utilizar preguntas breves y confirmar lo que ha expresado.", "moderada": "presentar dos objetos reales, uno junto al otro, y aceptar señalamiento o gestos.", "avanzada": "presentar una opción por vez. Considerar la mirada o el movimiento como posibles señales que deben confirmarse con su respuesta habitual y el contexto. Respetar el rechazo y detenerse si aparece malestar."}$c$::jsonb, precaucion = $c$Ofrecer elecciones reales y apropiadas. No utilizar esta actividad para tomar decisiones clínicas, económicas o de consentimiento complejo. Una respuesta ambigua no debe interpretarse automáticamente como aceptación.$c$, ciencia = $c${"gancho": "¿Sabías que elegir qué música escuchar o qué ropa ponerse también es una oportunidad para comunicarnos?", "evidencia": "Al ofrecer opciones, damos espacio para comprender, expresar gustos y participar en las decisiones del día a día.", "cierre": "Hoy vamos a practicar cómo expresar y escuchar esas preferencias. Las palabras, los gestos y el señalamiento pueden ayudarnos a comunicar una elección. Lo importante es dar tiempo para responder, confirmar lo que la persona quiere y respetar su decisión. 💬🧠"}$c$::jsonb, extras = null, niveles_cognitivos = array[$c$leve$c$, $c$moderada$c$, $c$avanzada$c$]::text[], duracion = $c$De 3 a 10 minutos, según la interacción.$c$, frecuencia = $c$Integrar en oportunidades cotidianas, sin convertir cada decisión en un ejercicio.$c$, orden = 23, estado_clinico = 'aprobado', adaptacion = null, por_que = null, objetivo = null, progresion = null, requisito = null, dominios = null, updated_at = now() where codigo = $c$COG-023$c$;
insert into public.media_resources_interno (resource_id, objetivo, objetivo_esperado, areas_trabajo, progresion, reglas, etiquetas)
select id, $c$Facilitar la expresión de preferencias y el intercambio comunicativo mediante opciones concretas.$c$, $c$Facilitar que la persona exprese una preferencia o una respuesta de aceptación o rechazo y que el familiar la reconozca y respete.$c$, array[$c$Comprensión de opciones$c$, $c$Expresión de preferencias$c$, $c$Comunicación verbal y no verbal$c$, $c$Turnos de interacción$c$, $c$Participación en decisiones cotidianas$c$]::text[], $c$Expresar aceptación o rechazo → elegir entre dos opciones → explicar una preferencia → mantener una conversación breve sobre la elección.$c$, $c$Ofrecer opciones reales. Dar tiempo y confirmar la respuesta. En demencia severa, no atribuir significado definitivo a una señal aislada.$c$, array[$c$Lenguaje funcional$c$, $c$preferencias$c$, $c$comunicación no verbal$c$, $c$interacción$c$, $c$autonomía cotidiana$c$]::text[] from public.media_resources where codigo = $c$COG-023$c$
on conflict (resource_id) do update set objetivo = excluded.objetivo, objetivo_esperado = excluded.objetivo_esperado, areas_trabajo = excluded.areas_trabajo, progresion = excluded.progresion, reglas = excluded.reglas, etiquetas = excluded.etiquetas, updated_at = now();

update public.media_resources set titulo = $c$Escucho, hago y compruebo$c$, detalle = $c$Hoy realizaremos «Escucho, hago y compruebo». Vamos a escuchar una indicación, realizarla y revisar juntos lo que hicimos. Pueden practicar sentados frente a una mesa. 🥄$c$, perfil = $c$Preventivo. · Deterioro cognitivo leve. · Demencia leve, con instrucciones sencillas. · Demencia moderada, mediante una acción inmediata con demostración.$c$, materiales = $c$Una servilleta, una cuchara, un vaso plástico y una bandeja. Utilizar objetos seguros y fáciles de manipular.$c$, pasos = $c$["Coloquen los objetos sobre la mesa, al alcance de la persona.", "Expliquen: «Voy a decirle algo que haremos con estos objetos».", "Comiencen con una indicación: «Ponga la cuchara en la bandeja».", "Antes de actuar, inviten a repetir o señalar lo que va a hacer, si le resulta posible.", "Permitan que complete la acción sin apresurarla.", "Revisen juntos: «La cuchara quedó en la bandeja».", "Si resulta sencillo, propongan dos acciones: «Ponga la cuchara en la bandeja y después coloque la servilleta junto al vaso»."]$c$::jsonb, ayuda = $c$Repitan la indicación con las mismas palabras. Si aún resulta difícil, divídanla y señalen el objeto o el lugar correspondiente. También pueden mostrar primero cómo hacerlo.$c$, adaptacion_por_etapa = $c${"preventivo": "comenzar con dos acciones y aumentar gradualmente a tres, según facilidad. Invitar a repetir el plan antes de ejecutarlo.", "dcl": "comenzar con una acción. Incorporar una segunda cuando la primera versión resulte cómoda. Permitir repetición y apoyos visibles.", "leve": "dar una instrucción concreta por vez. Mantener pocos objetos sobre la mesa y acompañar con gestos cuando sea necesario.", "moderada": "presentar un objeto y modelar una acción inmediata: «Pongamos la servilleta aquí». Omitir las secuencias.", "avanzada": "no utilizar la versión de retención de instrucciones. Elegir una actividad de participación acompañada en una sola acción."}$c$::jsonb, precaucion = $c$Evitar instrucciones ambiguas, objetos peligrosos o movimientos fuera del alcance. Si la persona no realiza la acción, comprobar primero que escuchó y comprendió la indicación.$c$, ciencia = $c${"gancho": "¿Sabías que utilizamos la memoria de trabajo cuando mantenemos una indicación en mente mientras la cumplimos?", "evidencia": "Por ejemplo, cuando nos piden buscar una servilleta y colocarla en la mesa.", "cierre": "Hoy vamos a practicar esa habilidad con acciones sencillas. Escuchar, repetir el plan y hacerlo por partes nos permite organizar lo que vamos a hacer. 🧠"}$c$::jsonb, extras = null, niveles_cognitivos = array[$c$preventivo$c$, $c$dcl$c$, $c$leve$c$, $c$moderada$c$]::text[], duracion = $c$De 5 a 10 minutos; reducir en demencia moderada.$c$, frecuencia = $c$De 2 a 3 veces por semana.$c$, orden = 24, estado_clinico = 'aprobado', adaptacion = null, por_que = null, objetivo = null, progresion = null, requisito = null, dominios = null, updated_at = now() where codigo = $c$COG-024$c$;
insert into public.media_resources_interno (resource_id, objetivo, objetivo_esperado, areas_trabajo, progresion, reglas, etiquetas)
select id, $c$Practicar el mantenimiento de una instrucción breve mientras se realiza una acción con objetos cotidianos.$c$, $c$Facilitar que la persona mantenga una indicación breve durante el tiempo necesario para realizarla, con los apoyos que requiera.$c$, array[$c$Memoria de trabajo$c$, $c$Atención auditiva$c$, $c$Comprensión verbal$c$, $c$Secuenciación de acciones$c$, $c$Revisión de lo realizado$c$]::text[], $c$Realizar una acción con demostración → seguir una indicación verbal → completar dos acciones consecutivas → realizar una secuencia breve sin recordatorios, si resulta cómodo.$c$, $c$Comenzar con una acción. Aumentar los pasos únicamente si resulta cómodo. Permitir repetición y demostración.$c$, array[$c$Memoria de trabajo$c$, $c$atención$c$, $c$instrucciones$c$, $c$secuenciación$c$, $c$objetos cotidianos$c$]::text[] from public.media_resources where codigo = $c$COG-024$c$
on conflict (resource_id) do update set objetivo = excluded.objetivo, objetivo_esperado = excluded.objetivo_esperado, areas_trabajo = excluded.areas_trabajo, progresion = excluded.progresion, reglas = excluded.reglas, etiquetas = excluded.etiquetas, updated_at = now();

update public.media_resources set titulo = $c$Un nombre, una conexión$c$, detalle = $c$Hoy realizaremos «Un nombre, una conexión». Vamos a relacionar un nombre con algo conocido para tener una pista que nos ayude a recordarlo. Pueden comenzar con un solo nombre. 👤$c$, perfil = $c$Preventivo. · Deterioro cognitivo leve. · Demencia leve, si comprende la asociación y participa sin malestar.$c$, materiales = $c$Una fotografía de una persona cuyo nombre se quiera aprender. También puede utilizarse un personaje ficticio o practicar con alguien presente.$c$, pasos = $c$["Presenten a la persona o su fotografía: «Ella se llama Rosa».", "Repitan el nombre juntos, sin exigir varias repeticiones.", "Busquen una conexión que tenga sentido para quien aprende: «Rosa, como la flor que tiene en el jardín».", "Construyan una frase breve: «Rosa, como las rosas de mi jardín».", "Utilicen el nombre en una conversación natural: «Rosa viene a acompañarnos hoy».", "Después de una pausa breve, ofrezcan la conexión como pista: «Su nombre es como una flor del jardín…».", "Si no lo recuerda, proporcionen el nombre y repitan juntos la relación."]$c$::jsonb, ayuda = $c$Propongan una asociación sencilla y comprueben que la comprende. Si la referencia no le resulta familiar, busquen otra o utilicen directamente una tarjeta con el nombre.$c$, adaptacion_por_etapa = $c${"preventivo": "invitar a crear su propia asociación. Practicar un segundo nombre cuando el primero resulte familiar.", "dcl": "trabajar un nombre por vez, con fotografía y frase escrita si ayuda. Mantener la misma asociación durante la práctica.", "leve": "el familiar propone una conexión concreta y acompaña el uso del nombre. Si la asociación confunde, utilizar la fotografía con el nombre visible.", "moderada": "no utilizar como ejercicio de aprendizaje de nombres. Presentarse con naturalidad y aportar el nombre y el vínculo cuando sea necesario.", "avanzada": "no utilizar como ejercicio de aprendizaje de nombres. Presentarse con naturalidad y aportar el nombre y el vínculo cuando sea necesario."}$c$::jsonb, precaucion = $c$Evitar apodos o asociaciones sobre características físicas que puedan resultar incómodas. No preguntar repetidamente «¿cómo me llamo?» ni interpretar el olvido del nombre como falta de afecto.$c$, ciencia = $c${"gancho": "¿Sabías que un nombre puede resultar más fácil de recordar cuando lo conectamos con algo que ya conocemos?", "evidencia": "Esa relación nos ofrece una pista: «Rosa, como la flor de mi jardín».", "cierre": "Hoy vamos a crear una conexión personal y utilizar el nombre en una conversación. La mejor pista será la que tenga sentido para la persona que está aprendiendo. 🌹🧠"}$c$::jsonb, extras = null, niveles_cognitivos = array[$c$preventivo$c$, $c$dcl$c$, $c$leve$c$]::text[], duracion = $c$De 5 a 8 minutos.$c$, frecuencia = $c$Practicar brevemente en distintas ocasiones cuando exista un nombre útil que aprender.$c$, orden = 25, estado_clinico = 'aprobado', adaptacion = null, por_que = null, objetivo = null, progresion = null, requisito = null, dominios = null, updated_at = now() where codigo = $c$COG-025$c$;
insert into public.media_resources_interno (resource_id, objetivo, objetivo_esperado, areas_trabajo, progresion, reglas, etiquetas)
select id, $c$Practicar una estrategia para aprender un nombre mediante una referencia conocida y significativa.$c$, $c$Favorecer que la persona construya y utilice una asociación como apoyo para recordar un nombre concreto.$c$, array[$c$Atención al nombre$c$, $c$Asociación semántica$c$, $c$Aprendizaje de información nueva$c$, $c$Recuperación con pistas$c$, $c$Lenguaje$c$]::text[], $c$Escuchar un nombre → relacionarlo con una referencia conocida → recuperarlo con la pista → utilizarlo en una conversación.$c$, $c$Un nombre al inicio. Elegir referencias conocidas y respetuosas. Sustituir la asociación por un apoyo visible si genera confusión.$c$, array[$c$Nombres$c$, $c$memoria cotidiana$c$, $c$asociación$c$, $c$aprendizaje$c$, $c$pistas$c$]::text[] from public.media_resources where codigo = $c$COG-025$c$
