update public.media_resources set titulo = $c$Imaginemos una escena$c$, detalle = $c$Hoy realizaremos «Imaginemos una escena». Vamos a escuchar una descripción e imaginar cómo podría verse. Cada persona puede formar una escena diferente y contarla a su manera. 🌳$c$, perfil = $c$Preventivo. · Deterioro cognitivo leve. · Demencia leve, si comprende descripciones breves y disfruta imaginar.$c$, materiales = $c$Una descripción preparada por el familiar. Papel y lápices opcionales.$c$, pasos = $c$["Busquen un espacio tranquilo y expliquen: «Voy a describir un lugar para que lo imaginemos».", "Lean despacio: «En un patio hay una mesa de madera. Encima de la mesa hay una taza azul. Junto a la mesa duerme un perro».", "Hagan una pausa para que la persona represente la escena. Puede mantener los ojos abiertos.", "Inviten a contar lo que imaginó: «¿Cómo era ese patio?» o «¿Qué había sobre la mesa?».", "Permitan que exprese la escena con palabras o un dibujo.", "Repitan la descripción cuando lo necesite y reconstruyan juntos los elementos."]$c$::jsonb, ayuda = $c$Presenten una frase por vez: «Imaginemos una mesa». Después agreguen un elemento: «Sobre la mesa hay una taza». Si imaginar no le resulta accesible, utilicen una fotografía y conversen sobre ella.$c$, adaptacion_por_etapa = $c${"preventivo": "añadir detalles de ubicación, colores o acciones. Pedir que relate la escena con sus propias palabras o invente una continuación.", "dcl": "utilizar dos o tres elementos y repetir la descripción por partes.", "leve": "comenzar con un objeto familiar y una ubicación sencilla. Aceptar respuestas breves y acompañar con preguntas concretas.", "moderada": "elegir una actividad con imágenes u objetos presentes, sin exigir la construcción de una escena mental.", "avanzada": "elegir una actividad con imágenes u objetos presentes, sin exigir la construcción de una escena mental."}$c$::jsonb, precaucion = $c$No todas las personas forman imágenes mentales con la misma facilidad. No insistir ni pedir cerrar los ojos. Evitar escenas que provoquen miedo o recuerdos desagradables.$c$, ciencia = $c${"gancho": "¿Sabías que algunas personas utilizan imágenes mentales como apoyo para recordar?", "evidencia": "Imaginar una taza azul sobre una mesa permite relacionar los detalles dentro de una misma escena.", "cierre": "Hoy vamos a explorar esta estrategia escuchando una descripción breve. Podemos contar lo imaginado o dibujarlo; cada persona encontrará la forma que le resulte más cómoda. 🧠🎨"}$c$::jsonb, extras = null, niveles_cognitivos = array[$c$preventivo$c$, $c$dcl$c$, $c$leve$c$]::text[], duracion = $c$De 5 a 10 minutos.$c$, frecuencia = $c$De 1 a 2 veces por semana.$c$, orden = 26, estado_clinico = 'aprobado', adaptacion = null, por_que = null, objetivo = null, progresion = null, requisito = null, dominios = null, updated_at = now() where codigo = $c$COG-026$c$;
insert into public.media_resources_interno (resource_id, objetivo, objetivo_esperado, areas_trabajo, progresion, reglas, etiquetas)
select id, $c$Practicar la representación mental de una descripción breve y su expresión mediante palabras o dibujos.$c$, $c$Facilitar que la persona represente y comunique algunos elementos de una descripción breve, con repetición o apoyos cuando sean necesarios.$c$, array[$c$Comprensión verbal$c$, $c$Representación mental$c$, $c$Memoria de detalles$c$, $c$Relaciones espaciales$c$, $c$Expresión oral o gráfica$c$]::text[], $c$Imaginar un objeto → ubicarlo en un lugar → integrar dos o tres elementos → describir una escena algo más extensa.$c$, $c$No exigir imágenes mentales nítidas. Comenzar con pocos elementos. Sustituir por una imagen visible si la propuesta resulta difícil.$c$, array[$c$Visualización$c$, $c$comprensión$c$, $c$memoria$c$, $c$representación mental$c$, $c$relaciones espaciales$c$]::text[] from public.media_resources where codigo = $c$COG-026$c$
on conflict (resource_id) do update set objetivo = excluded.objetivo, objetivo_esperado = excluded.objetivo_esperado, areas_trabajo = excluded.areas_trabajo, progresion = excluded.progresion, reglas = excluded.reglas, etiquetas = excluded.etiquetas, updated_at = now();

update public.media_resources set titulo = $c$¿Qué iba a buscar?$c$, detalle = $c$Hoy realizaremos «¿Qué iba a buscar?». Vamos a practicar cómo mantener presente una tarea sencilla antes de comenzarla. Podemos decir lo que vamos a hacer y llevar una pista si la necesitamos. 🏡$c$, perfil = $c$Preventivo. · Deterioro cognitivo leve. · Demencia leve, con un objeto visible o una pista. · Demencia moderada, mediante una acción inmediata y acompañada.$c$, materiales = $c$Un objeto cotidiano seguro, como una servilleta o un estuche. Opcionalmente, una tarjeta con su nombre o fotografía.$c$, pasos = $c$["Elijan una acción breve y útil: «Voy a buscar una servilleta para la mesa».", "Antes de comenzar, inviten a expresar el propósito con sus propias palabras.", "Identifiquen dónde está el objeto. Al inicio, colóquenlo cerca y a la vista.", "Realicen la acción y vuelvan al punto de inicio.", "Comprueben juntos: «Fuimos a buscar la servilleta y aquí está».", "Si resulta cómodo, practiquen en otra ocasión con un objeto que esté un poco más lejos, manteniendo un recorrido seguro."]$c$::jsonb, ayuda = $c$Utilicen una tarjeta o fotografía que pueda llevar consigo. Si pierde el propósito, recuerden la acción con naturalidad: «Íbamos a buscar la servilleta para la mesa», y acompáñenla.$c$, adaptacion_por_etapa = $c${"preventivo": "practicar una intención real y breve en otra zona de la casa. Invitar a expresar qué va a buscar y para qué, sin añadir distracciones artificiales.", "dcl": "utilizar un solo objeto y una tarjeta de apoyo. Mantener un recorrido corto.", "leve": "elegir un objeto cercano, aportar una pista visible y acompañar cuando sea necesario.", "moderada": "presentar el objeto al alcance y realizar juntos una acción inmediata: «Tomemos la servilleta para la mesa». Omitir desplazamientos y pausas.", "avanzada": "no utilizar como ejercicio de mantenimiento de una intención. Elegir una acción acompañada con el objeto presente."}$c$::jsonb, precaucion = $c$Puede realizarse completamente sentado. Evitar escaleras, superficies inestables y objetos difíciles de alcanzar. No introducir interrupciones para comprobar si la persona olvida la tarea.$c$, ciencia = $c${"gancho": "¿Sabías que recordar lo que vamos a hacer también forma parte de la memoria?", "evidencia": "La utilizamos cuando nos levantamos para buscar algo o llevamos un objeto de una habitación a otra.", "cierre": "Hoy vamos a practicar cómo mantener ese propósito presente. Decirlo antes de actuar y utilizar una nota o una imagen puede servirnos de apoyo durante el recorrido. 🧠"}$c$::jsonb, extras = null, niveles_cognitivos = array[$c$preventivo$c$, $c$dcl$c$, $c$leve$c$, $c$moderada$c$]::text[], duracion = $c$De 3 a 8 minutos.$c$, frecuencia = $c$Integrar en situaciones cotidianas, evitando repeticiones innecesarias.$c$, orden = 27, estado_clinico = 'aprobado', adaptacion = null, por_que = null, objetivo = null, progresion = null, requisito = null, dominios = null, updated_at = now() where codigo = $c$COG-027$c$;
insert into public.media_resources_interno (resource_id, objetivo, objetivo_esperado, areas_trabajo, progresion, reglas, etiquetas)
select id, $c$Practicar una estrategia para mantener presente una intención breve mientras se busca un objeto.$c$, $c$Facilitar que la persona complete una intención breve utilizando una frase, una señal visible o acompañamiento.$c$, array[$c$Memoria de intenciones$c$, $c$Memoria de trabajo$c$, $c$Atención dirigida$c$, $c$Organización de una acción$c$, $c$Uso de apoyos externos$c$]::text[], $c$Buscar un objeto visible → repetir el propósito antes de actuar → buscarlo a corta distancia con una pista → completar la acción en otra zona conocida y segura.$c$, $c$Una intención por vez. Priorizar la seguridad y permitir apoyos. En demencia moderada, realizar una acción inmediata con el objeto presente.$c$, array[$c$Memoria cotidiana$c$, $c$intenciones$c$, $c$atención$c$, $c$apoyos externos$c$, $c$acciones funcionales$c$]::text[] from public.media_resources where codigo = $c$COG-027$c$
on conflict (resource_id) do update set objetivo = excluded.objetivo, objetivo_esperado = excluded.objetivo_esperado, areas_trabajo = excluded.areas_trabajo, progresion = excluded.progresion, reglas = excluded.reglas, etiquetas = excluded.etiquetas, updated_at = now();

update public.media_resources set titulo = $c$Observo para una misión$c$, detalle = $c$Hoy realizaremos «Observo para una misión». Vamos a observar varios objetos y buscar cuáles nos servirían para una tarea cotidiana. Antes de comenzar, tendremos una misión clara. 🔎$c$, perfil = $c$Preventivo. · Deterioro cognitivo leve. · Demencia leve. · Demencia moderada, con pocos objetos y una indicación sencilla.$c$, materiales = $c$De cuatro a ocho objetos seguros, como una servilleta, una cuchara, un vaso plástico, un peine, un libro y un sombrero.$c$, pasos = $c$["Coloquen los objetos separados sobre una mesa.", "Presenten una misión: «Vamos a buscar lo que necesitamos para poner la mesa».", "Permitan que la persona observe y seleccione los elementos.", "Conversen sobre sus elecciones: «¿Cómo utilizaríamos esto?».", "Acepten respuestas diferentes cuando tengan una explicación razonable.", "Cambien la misión si la persona desea continuar: «Ahora busquemos algo que nos sirva para arreglarnos antes de salir»."]$c$::jsonb, ayuda = $c$Reduzcan la cantidad de objetos. Ofrezcan dos opciones: «¿Para poner la mesa necesitamos la servilleta o el peine?». También pueden mostrar primero un ejemplo.$c$, adaptacion_por_etapa = $c${"preventivo": "presentar entre seis y ocho objetos y plantear misiones que permitan distintas soluciones. Invitar a explicar qué elegiría y por qué.", "dcl": "utilizar cuatro objetos y mantener la misión escrita o repetirla cuando sea necesario.", "leve": "elegir tareas muy familiares y presentar tres o cuatro objetos. Dar una indicación por vez.", "moderada": "ofrecer dos objetos claramente diferentes y pedir una elección concreta: «¿Cuál usamos para peinarnos?». Aceptar señalamiento.", "avanzada": "no utilizar la versión de selección por propósito. Preferir exploración acompañada de un objeto familiar."}$c$::jsonb, precaucion = $c$Utilizar objetos visibles, seguros y fáciles de reconocer. Evitar convertir las elecciones en respuestas rígidamente correctas o incorrectas.$c$, ciencia = $c${"gancho": "¿Sabías que tener una misión nos ayuda a orientar la atención?", "evidencia": "Cuando buscamos algo para una tarea concreta, necesitamos fijarnos en lo que resulta útil y dejar otros elementos en segundo plano.", "cierre": "Hoy vamos a observar con un propósito, elegir y explicar nuestras decisiones. Una habilidad que también utilizamos al preparar una merienda o buscar lo necesario para salir. 🔎🧠"}$c$::jsonb, extras = null, niveles_cognitivos = array[$c$preventivo$c$, $c$dcl$c$, $c$leve$c$, $c$moderada$c$]::text[], duracion = $c$De 5 a 10 minutos.$c$, frecuencia = $c$De 1 a 2 veces por semana.$c$, orden = 28, estado_clinico = 'aprobado', adaptacion = null, por_que = null, objetivo = null, progresion = null, requisito = null, dominios = null, updated_at = now() where codigo = $c$COG-028$c$;
insert into public.media_resources_interno (resource_id, objetivo, objetivo_esperado, areas_trabajo, progresion, reglas, etiquetas)
select id, $c$Practicar la atención dirigida mediante la búsqueda de objetos que respondan a un propósito concreto.$c$, $c$Facilitar que la persona seleccione uno o varios objetos de acuerdo con una finalidad cotidiana, con los apoyos necesarios.$c$, array[$c$Atención selectiva$c$, $c$Comprensión verbal$c$, $c$Conocimiento del uso de los objetos$c$, $c$Razonamiento práctico$c$, $c$Expresión de decisiones$c$]::text[], $c$Elegir entre dos objetos → seleccionar varios elementos útiles → explicar las elecciones → proponer una misión para el familiar.$c$, $c$Definir la misión antes de observar. Ajustar la cantidad de objetos y aceptar elecciones justificadas.$c$, array[$c$Atención selectiva$c$, $c$objetos cotidianos$c$, $c$razonamiento$c$, $c$comprensión$c$, $c$decisiones$c$]::text[] from public.media_resources where codigo = $c$COG-028$c$
