update public.media_resources set titulo = $c$Un mensaje para compartir$c$, detalle = $c$Hoy realizaremos «Un mensaje para compartir». Vamos a escuchar una información breve y contarla con nuestras propias palabras. Podemos pedir que la repitan o anotar una pista. 💬$c$, perfil = $c$Preventivo. · Deterioro cognitivo leve. · Demencia leve, con mensajes sencillos y apoyos.$c$, materiales = $c$Un mensaje preparado por el familiar. Papel y lápiz opcionales.$c$, pasos = $c$["Expliquen: «Voy a darle un mensaje para que después me cuente lo importante».", "Lean un mensaje sencillo: «Para la merienda de hoy vamos a poner el pan y las servilletas en la mesa».", "Pregunten: «¿Qué tenemos que preparar?».", "Permitan que lo comunique con sus propias palabras.", "Repitan juntos la información si hace falta.", "Si hay otra persona disponible y desea participar, invítenla a escuchar el mensaje. También pueden intercambiar los papeles."]$c$::jsonb, ayuda = $c$Dividan el mensaje: «Vamos a preparar la merienda. Necesitamos pan y servilletas». Permitan anotarlo, dibujarlo o utilizar imágenes.$c$, adaptacion_por_etapa = $c${"preventivo": "utilizar mensajes con dos o tres datos, como qué se necesita y dónde colocarlo. Invitar a identificar lo esencial.", "dcl": "comenzar con una idea principal. Permitir repetir el mensaje y utilizar una nota.", "leve": "comunicar una frase breve y pedir que la comparta inmediatamente. Aceptar palabras sueltas o señalamiento de los objetos.", "moderada": "no utilizar como tarea de retención y transmisión de mensajes. Preferir comunicación inmediata sobre objetos o acciones presentes.", "avanzada": "no utilizar como tarea de retención y transmisión de mensajes. Preferir comunicación inmediata sobre objetos o acciones presentes."}$c$::jsonb, precaucion = $c$Practicar con información sin consecuencias importantes. No utilizar indicaciones sobre medicamentos, citas médicas o asuntos urgentes como prueba de recuerdo.$c$, ciencia = $c${"gancho": "¿Sabías que compartir un mensaje requiere escuchar, comprender y mantener presente lo importante?", "evidencia": "No hace falta repetir cada palabra: muchas veces basta con comunicar la idea principal.", "cierre": "Hoy vamos a practicar con mensajes cotidianos. Pedir que nos repitan algo o usar una nota también son formas útiles de ayudarnos a recordar. 💬🧠"}$c$::jsonb, extras = null, niveles_cognitivos = array[$c$preventivo$c$, $c$dcl$c$, $c$leve$c$]::text[], duracion = $c$De 5 a 8 minutos.$c$, frecuencia = $c$De 1 a 2 veces por semana.$c$, orden = 29, estado_clinico = 'aprobado', adaptacion = null, por_que = null, objetivo = null, progresion = null, requisito = null, dominios = null, updated_at = now() where codigo = $c$COG-029$c$;
insert into public.media_resources_interno (resource_id, objetivo, objetivo_esperado, areas_trabajo, progresion, reglas, etiquetas)
select id, $c$Practicar la comprensión, el mantenimiento y la comunicación de un mensaje breve.$c$, $c$Favorecer que la persona comunique la idea principal de un mensaje breve utilizando sus propias palabras o apoyos.$c$, array[$c$Comprensión auditiva$c$, $c$Memoria de trabajo$c$, $c$Memoria reciente$c$, $c$Identificación de ideas principales$c$, $c$Expresión oral$c$]::text[], $c$Comunicar una idea inmediatamente → transmitir dos datos relacionados → utilizar una palabra clave → compartir el mensaje después de una pausa breve.$c$, $c$Comenzar con una idea. Permitir repetición y notas. Evitar mensajes cuya pérdida pueda generar riesgos.$c$, array[$c$Memoria cotidiana$c$, $c$mensajes$c$, $c$comprensión$c$, $c$comunicación$c$, $c$apoyos externos$c$]::text[] from public.media_resources where codigo = $c$COG-029$c$
on conflict (resource_id) do update set objetivo = excluded.objetivo, objetivo_esperado = excluded.objetivo_esperado, areas_trabajo = excluded.areas_trabajo, progresion = excluded.progresion, reglas = excluded.reglas, etiquetas = excluded.etiquetas, updated_at = now();

update public.media_resources set titulo = $c$Una palabra me lleva a otra$c$, detalle = $c$Hoy realizaremos «Una palabra me lleva a otra». Vamos a descubrir cómo una idea puede conectarse con la siguiente. Cada persona puede encontrar relaciones diferentes. 🔗$c$, perfil = $c$Preventivo. · Deterioro cognitivo leve. · Demencia leve. · Demencia moderada, mediante asociaciones entre dos elementos visibles.$c$, materiales = $c$Papel y lápiz. Opcionalmente, fotografías u objetos cotidianos.$c$, pasos = $c$["Comiencen con una palabra familiar: «lluvia».", "Pregunten: «¿Qué le hace pensar esa palabra?».", "Si responde «paraguas», comenten la conexión: «Usamos el paraguas cuando llueve».", "Continúen desde la nueva palabra: «¿Y paraguas con qué lo relaciona?».", "Escriban o representen la cadena: lluvia–paraguas–puerta–casa.", "Lean juntos la secuencia y conversen sobre las conexiones. Las palabras pueden permanecer visibles durante toda la actividad."]$c$::jsonb, ayuda = $c$Ofrezcan una relación para completar: «Cuando llueve, para no mojarnos usamos…». También pueden presentar dos imágenes para elegir.$c$, adaptacion_por_etapa = $c${"preventivo": "construir cadenas más extensas y explorar distintas asociaciones para una misma palabra.", "dcl": "mantener una cadena de tres o cuatro palabras visibles y repasar cada conexión.", "leve": "utilizar palabras concretas, fotografías u objetos. Trabajar pocas relaciones y aportar ejemplos.", "moderada": "presentar dos elementos relacionados, como una taza y una cuchara, y conversar sobre cómo se utilizan juntos. Omitir la cadena.", "avanzada": "no utilizar como ejercicio de asociación verbal."}$c$::jsonb, precaucion = $c$No imponer una única conexión. Si una respuesta no resulta clara, invitar a explicarla con curiosidad. Evitar asociaciones que generen angustia.$c$, ciencia = $c${"gancho": "¿Sabías que nuestros conocimientos están conectados?", "evidencia": "La palabra «lluvia» puede hacernos pensar en un paraguas, una ventana o una tarde en casa.", "cierre": "Hoy vamos a recorrer esas conexiones. Al explicar cómo se relacionan dos palabras, utilizamos el lenguaje y los conocimientos que hemos construido a lo largo de la vida. 🔗🧠"}$c$::jsonb, extras = null, niveles_cognitivos = array[$c$preventivo$c$, $c$dcl$c$, $c$leve$c$, $c$moderada$c$]::text[], duracion = $c$De 5 a 10 minutos.$c$, frecuencia = $c$De 1 a 2 veces por semana.$c$, orden = 30, estado_clinico = 'aprobado', adaptacion = null, por_que = null, objetivo = null, progresion = null, requisito = null, dominios = null, updated_at = now() where codigo = $c$COG-030$c$;
insert into public.media_resources_interno (resource_id, objetivo, objetivo_esperado, areas_trabajo, progresion, reglas, etiquetas)
select id, $c$Explorar relaciones entre palabras y construir una secuencia de asociaciones con significado.$c$, $c$Facilitar que la persona establezca y comunique relaciones entre palabras u objetos, con ejemplos o apoyos visibles.$c$, array[$c$Memoria semántica$c$, $c$Asociación de ideas$c$, $c$Acceso a palabras$c$, $c$Flexibilidad$c$, $c$Explicación verbal$c$]::text[], $c$Relacionar dos elementos → construir una cadena de tres palabras → ampliar la cadena → explicar las conexiones o inventar una historia breve.$c$, $c$Mantener las palabras visibles si ayuda. Aceptar asociaciones personales. En demencia moderada, trabajar únicamente con dos elementos presentes.$c$, array[$c$Lenguaje$c$, $c$memoria semántica$c$, $c$asociación$c$, $c$flexibilidad$c$, $c$conversación$c$]::text[] from public.media_resources where codigo = $c$COG-030$c$
on conflict (resource_id) do update set objetivo = excluded.objetivo, objetivo_esperado = excluded.objetivo_esperado, areas_trabajo = excluded.areas_trabajo, progresion = excluded.progresion, reglas = excluded.reglas, etiquetas = excluded.etiquetas, updated_at = now();

update public.media_resources set titulo = $c$Lo nuevo se parece a…$c$, detalle = $c$Hoy realizaremos «Lo nuevo se parece a…». Vamos a conocer un objeto y buscar en qué se parece a otro que ya utilizamos. Observar sus semejanzas puede ayudarnos a comprender para qué sirve. 🧐$c$, perfil = $c$Preventivo. · Deterioro cognitivo leve. · Demencia leve, con objetos concretos y demostración.$c$, materiales = $c$Un objeto seguro y poco conocido para la persona y otro familiar con alguna semejanza. Por ejemplo, un batidor de silicona y un tenedor.$c$, pasos = $c$["Presenten el objeto poco conocido y expliquen su nombre y función.", "Permitan observarlo y manipularlo si es seguro.", "Coloquen junto a él un objeto familiar.", "Pregunten: «¿En qué se parecen?» o «¿Podemos usarlos para algo parecido?».", "Muestren una diferencia importante: «Los dos pueden mezclar, pero tienen distinta forma».", "Construyan una frase: «Este batidor se parece al tenedor porque ambos nos ayudan a mezclar».", "Cierren repasando el nombre y el uso, sin exigir que los recuerde después."]$c$::jsonb, ayuda = $c$Señalen una característica concreta: «Los dos tienen mango». Muestren la acción y permitan imitarla.$c$, adaptacion_por_etapa = $c${"preventivo": "elegir un objeto que despierte curiosidad y comparar forma, material, función y situaciones de uso.", "dcl": "presentar una sola comparación y construir juntos una frase sencilla.", "leve": "utilizar un objeto solo ligeramente diferente de otro conocido. Priorizar la demostración y las características visibles.", "moderada": "no utilizar como aprendizaje de objetos nuevos. Preferir reconocimiento y uso acompañado de objetos familiares.", "avanzada": "no utilizar como aprendizaje de objetos nuevos. Preferir reconocimiento y uso acompañado de objetos familiares."}$c$::jsonb, precaucion = $c$Evitar objetos cortantes, eléctricos o que puedan confundirse con alimentos. Explicar también las diferencias: parecerse no significa que ambos puedan utilizarse de la misma manera.$c$, ciencia = $c${"gancho": "¿Sabías que para comprender algo nuevo solemos buscarle un parecido con algo conocido?", "evidencia": "Comparar su forma o su función nos da un punto de partida para entenderlo.", "cierre": "Hoy vamos a utilizar esa estrategia con un objeto. Buscaremos semejanzas y diferencias para darle sentido a la información nueva. 🧠"}$c$::jsonb, extras = null, niveles_cognitivos = array[$c$preventivo$c$, $c$dcl$c$, $c$leve$c$]::text[], duracion = $c$De 5 a 10 minutos.$c$, frecuencia = $c$Una vez por semana o cuando surja un objeto apropiado.$c$, orden = 31, estado_clinico = 'aprobado', adaptacion = null, por_que = null, objetivo = null, progresion = null, requisito = null, dominios = null, updated_at = now() where codigo = $c$COG-031$c$;
insert into public.media_resources_interno (resource_id, objetivo, objetivo_esperado, areas_trabajo, progresion, reglas, etiquetas)
select id, $c$Relacionar un objeto poco conocido con conocimientos previos mediante la comparación de características y funciones.$c$, $c$Facilitar que la persona identifique una semejanza o diferencia entre dos objetos y comprenda el uso del objeto presentado.$c$, array[$c$Observación$c$, $c$Comparación$c$, $c$Memoria semántica$c$, $c$Comprensión de información nueva$c$, $c$Lenguaje descriptivo$c$]::text[], $c$Reconocer una semejanza → identificar una diferencia → explicar el uso → relacionar otro objeto con algo conocido.$c$, $c$Comparar dos objetos seguros. Explicar nombre y función antes de preguntar. No exigir aprendizaje posterior.$c$, array[$c$Asociación$c$, $c$comparación$c$, $c$conocimientos previos$c$, $c$comprensión$c$, $c$objetos$c$]::text[] from public.media_resources where codigo = $c$COG-031$c$
on conflict (resource_id) do update set objetivo = excluded.objetivo, objetivo_esperado = excluded.objetivo_esperado, areas_trabajo = excluded.areas_trabajo, progresion = excluded.progresion, reglas = excluded.reglas, etiquetas = excluded.etiquetas, updated_at = now();

update public.media_resources set titulo = $c$Una idea, varias formas$c$, detalle = $c$Hoy realizaremos «Una idea, varias formas». Vamos a descubrir distintas maneras de expresar lo que necesitamos. Podemos usar una frase, señalar un objeto o acompañarnos con un gesto. 💬$c$, perfil = $c$Preventivo. · Deterioro cognitivo leve. · Demencia leve. · Demencia moderada, con ejemplos y opciones concretas. · Demencia severa, mediante respuestas comunicativas habituales y acompañamiento.$c$, materiales = $c$Tarjetas con situaciones cotidianas o fotografías. También pueden utilizarse objetos, como una manta o un vaso plástico vacío.$c$, pasos = $c$["Presenten una situación: «Imaginemos que tenemos frío».", "Den un ejemplo: «Podemos decir “tengo frío”».", "Inviten a buscar otra manera: «¿Qué podríamos pedir?».", "Propongan alternativas si hace falta: «Necesito una manta» o señalarla.", "Representen brevemente el intercambio: una persona expresa la necesidad y la otra responde.", "Practiquen otra situación, como pedir ayuda para alcanzar un objeto."]$c$::jsonb, ayuda = $c$Muestren el objeto y ofrezcan un modelo: «¿Quiere la manta?». Acepten palabras sueltas o gestos y confirmen lo que entendieron.$c$, adaptacion_por_etapa = $c${"preventivo": "proponer varias formas de expresar una idea y conversar sobre cuál resulta más clara en cada situación.", "dcl": "trabajar una situación por vez y permitir tiempo para formular la respuesta.", "leve": "utilizar ejemplos concretos, objetos y frases breves. Evitar exigir una formulación distinta si ya logra comunicar la idea.", "moderada": "el familiar modela una frase o gesto y ofrece opciones para expresar una necesidad presente.", "avanzada": "responder a las señales habituales de la persona y confirmar su posible significado. No exigir imitación ni atribuir una intención definitiva a una señal aislada."}$c$::jsonb, precaucion = $c$No provocar frío, sed u otra incomodidad para realizar el ejercicio. Si una respuesta es ambigua, comprobarla antes de actuar.$c$, ciencia = $c${"gancho": "¿Sabías que podemos comunicar una misma necesidad de diferentes maneras?", "evidencia": "Decir «tengo frío», pedir una manta o señalarla pueden ayudarnos a expresar lo que necesitamos.", "cierre": "Hoy vamos a explorar esas alternativas. Dar tiempo, observar y confirmar lo que entendimos ayuda a que la conversación continúe, incluso cuando cuesta encontrar una palabra. 💬🧠"}$c$::jsonb, extras = null, niveles_cognitivos = array[$c$preventivo$c$, $c$dcl$c$, $c$leve$c$, $c$moderada$c$, $c$avanzada$c$]::text[], duracion = $c$De 5 a 10 minutos; interacciones más breves en niveles avanzados.$c$, frecuencia = $c$De 1 a 2 veces por semana y en oportunidades naturales.$c$, orden = 32, estado_clinico = 'aprobado', adaptacion = null, por_que = null, objetivo = null, progresion = null, requisito = null, dominios = null, updated_at = now() where codigo = $c$COG-032$c$;
insert into public.media_resources_interno (resource_id, objetivo, objetivo_esperado, areas_trabajo, progresion, reglas, etiquetas)
select id, $c$Explorar distintas maneras de comunicar una necesidad o una idea mediante palabras, gestos y apoyos.$c$, $c$Favorecer que la persona encuentre una forma accesible de expresar una idea y que el familiar reconozca y confirme su mensaje.$c$, array[$c$Expresión de necesidades$c$, $c$Acceso a palabras$c$, $c$Flexibilidad verbal$c$, $c$Comunicación gestual$c$, $c$Intercambio comunicativo$c$]::text[], $c$Reconocer una necesidad → expresarla de una forma → explorar otra alternativa → utilizarla en un intercambio breve.$c$, $c$Aceptar palabras, gestos y señalamiento. En demencia avanzada, priorizar la comunicación presente y la confirmación.$c$, array[$c$Lenguaje funcional$c$, $c$necesidades$c$, $c$comunicación no verbal$c$, $c$expresión$c$, $c$interacción$c$]::text[] from public.media_resources where codigo = $c$COG-032$c$
