update public.media_resources set titulo = $c$Busquemos una pista$c$, detalle = $c$Hoy realizaremos «Busquemos una pista». Vamos a compartir una experiencia breve y después utilizar algunas pistas para recordar lo que hicimos. Podemos volver a mirar los materiales cuando lo necesitemos. 🔎$c$, perfil = $c$Preventivo. · Deterioro cognitivo leve. · Demencia leve, con una experiencia inmediata y apoyos.$c$, materiales = $c$Una actividad breve preparada por el familiar y sus elementos: por ejemplo, una imagen de un jardín y dos lápices de colores.$c$, pasos = $c$["Compartan una acción sencilla: observen una imagen y elijan un color que combine con ella.", "Conversen brevemente sobre otro tema.", "Inviten a retomar la experiencia: «Hace un momento elegimos un color. ¿Cuál fue?».", "Si no lo recuerda, aporten una pista concreta: «Estábamos mirando una imagen de un jardín».", "Si hace falta, muestren la imagen y después los dos lápices.", "Si el recuerdo no aparece, proporcionen la respuesta: «Elegimos el verde».", "Cierren reconstruyendo juntos lo que hicieron."]$c$::jsonb, ayuda = $c$Pasen pronto de la pregunta abierta al apoyo visible. No acumulen preguntas. Recordar juntos también es una forma válida de participar.$c$, adaptacion_por_etapa = $c${"preventivo": "comenzar con una pregunta abierta y explorar después pistas sobre el lugar, el tema o la acción.", "dcl": "utilizar una experiencia breve y una pausa corta. Ofrecer pistas concretas y permitir consultar los materiales.", "leve": "trabajar inmediatamente después de la acción. Mostrar los elementos y ofrecer dos opciones si es necesario.", "moderada": "no utilizar como tarea de recuperación de una experiencia reciente. Preferir conversación sobre lo que está presente.", "avanzada": "no utilizar como tarea de recuperación de una experiencia reciente. Preferir conversación sobre lo que está presente."}$c$::jsonb, precaucion = $c$No utilizar recuerdos de conflictos, pérdidas o situaciones importantes. Las pistas pueden ayudar, pero no garantizan que aparezca el recuerdo. No insistir ni sugerir detalles que no ocurrieron.$c$, ciencia = $c${"gancho": "¿Sabías que a veces un lugar, un objeto o un tema nos da una pista para recordar?", "evidencia": "Por eso podemos recuperar una idea al volver a mirar lo que estábamos haciendo.", "cierre": "Hoy vamos a explorar esas pistas con una experiencia sencilla. Si el recuerdo no aparece, podemos reconstruirlo juntos y continuar. 🔎🧠"}$c$::jsonb, extras = null, niveles_cognitivos = array[$c$preventivo$c$, $c$dcl$c$, $c$leve$c$]::text[], duracion = $c$De 5 a 8 minutos.$c$, frecuencia = $c$De 1 a 2 veces por semana.$c$, orden = 33, estado_clinico = 'aprobado', adaptacion = null, por_que = null, objetivo = null, progresion = null, requisito = null, dominios = null, updated_at = now() where codigo = $c$COG-033$c$;
insert into public.media_resources_interno (resource_id, objetivo, objetivo_esperado, areas_trabajo, progresion, reglas, etiquetas)
select id, $c$Practicar el uso de claves de contexto para recuperar información de una experiencia reciente y sencilla.$c$, $c$Facilitar que la persona utilice una pista verbal o visual para recordar o reconocer un detalle de una experiencia compartida.$c$, array[$c$Memoria episódica reciente$c$, $c$Recuperación con claves$c$, $c$Asociación con el contexto$c$, $c$Atención$c$, $c$Reconocimiento$c$]::text[], $c$Recordar con los materiales presentes → utilizar una pista verbal → retomar la experiencia después de una pausa breve → reconocer qué tipo de pista le resultó útil.$c$, $c$Utilizar experiencias sencillas y verificables. Ofrecer apoyos progresivos y proporcionar la respuesta si no aparece.$c$, array[$c$Memoria reciente$c$, $c$recuperación$c$, $c$pistas$c$, $c$contexto$c$, $c$reconocimiento$c$]::text[] from public.media_resources where codigo = $c$COG-033$c$
on conflict (resource_id) do update set objetivo = excluded.objetivo, objetivo_esperado = excluded.objetivo_esperado, areas_trabajo = excluded.areas_trabajo, progresion = excluded.progresion, reglas = excluded.reglas, etiquetas = excluded.etiquetas, updated_at = now();

update public.media_resources set titulo = $c$Lo hice y lo registro$c$, detalle = $c$Hoy realizaremos «Lo hice y lo registro». Vamos a realizar una tarea sencilla y dejar una señal de que está terminada. Después podremos consultar el registro. ✅$c$, perfil = $c$Preventivo. · Deterioro cognitivo leve. · Demencia leve, con una lista sencilla. · Demencia moderada, mediante una acción y registro acompañados.$c$, materiales = $c$Una hoja con una tarea escrita o representada con una imagen, un espacio para marcar y un lápiz. Un objeto seguro para realizar la acción.$c$, pasos = $c$["Elijan una acción sin riesgo, como guardar una revista en una cesta.", "Preparen una hoja que diga «Guardar la revista», con un espacio para marcar.", "Lean o expliquen juntos la tarea.", "Realicen la acción.", "Inmediatamente después, hagan una marca: «Ya guardamos la revista; ahora lo anotamos».", "Después de una pausa breve, consulten juntos la hoja: «Aquí podemos ver lo que ya hicimos».", "Para una nueva práctica, utilicen un registro claramente identificado como nuevo."]$c$::jsonb, ayuda = $c$Acompañen la secuencia completa: hacer la acción y marcar. Utilicen una fotografía en lugar de texto o permitan colocar una ficha grande sobre el espacio correspondiente.$c$, adaptacion_por_etapa = $c${"preventivo": "preparar una lista de dos o tres tareas sencillas y practicar marcar únicamente después de realizarlas.", "dcl": "comenzar con una sola tarea y mantener el registro cerca del lugar de la acción.", "leve": "utilizar una imagen y un espacio grande para marcar. El familiar comprueba que la señal corresponde a una tarea efectivamente realizada.", "moderada": "realizar una acción y marcar juntos inmediatamente. No exigir que consulte la hoja de manera independiente.", "avanzada": "no utilizar como sistema de seguimiento autónomo. Elegir actividades de participación directa sin exigencia de registro."}$c$::jsonb, precaucion = $c$Practicar inicialmente con acciones sin consecuencias importantes. No utilizar este ejercicio para decidir si se repite una dosis de medicamento. Evitar hojas antiguas o marcas confusas.$c$, ciencia = $c${"gancho": "¿Sabías que podemos dejar parte del trabajo de recordar en una ayuda visible?", "evidencia": "Una marca en una lista permite consultar qué hicimos sin depender únicamente del recuerdo.", "cierre": "Hoy vamos a practicar una secuencia sencilla: hacer, marcar y consultar. La señal será útil cuando represente con claridad una acción que realmente terminamos. ✅🧠"}$c$::jsonb, extras = null, niveles_cognitivos = array[$c$preventivo$c$, $c$dcl$c$, $c$leve$c$, $c$moderada$c$]::text[], duracion = $c$De 5 a 8 minutos.$c$, frecuencia = $c$Practicar con una rutina sencilla, según necesidad.$c$, orden = 34, estado_clinico = 'aprobado', adaptacion = null, por_que = null, objetivo = null, progresion = null, requisito = null, dominios = null, updated_at = now() where codigo = $c$COG-034$c$;
insert into public.media_resources_interno (resource_id, objetivo, objetivo_esperado, areas_trabajo, progresion, reglas, etiquetas)
select id, $c$Practicar el uso de un registro visible para comprobar si se realizó una acción cotidiana.$c$, $c$Favorecer que la persona participe en registrar una acción realizada y consultar esa señal, con supervisión según necesidad.$c$, array[$c$Atención a la acción$c$, $c$Secuenciación$c$, $c$Uso de apoyos externos$c$, $c$Comprobación de tareas$c$, $c$Organización cotidiana$c$]::text[], $c$Realizar y marcar con ayuda → completar una tarea y consultar el registro → utilizar una lista breve de dos acciones diferenciadas.$c$, $c$Marcar después de realizar la acción. Mantener el registro actualizado. En demencia, acompañar y verificar según capacidad.$c$, array[$c$Memoria cotidiana$c$, $c$registro$c$, $c$apoyos externos$c$, $c$rutinas$c$, $c$organización$c$]::text[] from public.media_resources where codigo = $c$COG-034$c$
on conflict (resource_id) do update set objetivo = excluded.objetivo, objetivo_esperado = excluded.objetivo_esperado, areas_trabajo = excluded.areas_trabajo, progresion = excluded.progresion, reglas = excluded.reglas, etiquetas = excluded.etiquetas, updated_at = now();

update public.media_resources set titulo = $c$Palabras que organizan$c$, detalle = $c$Hoy realizaremos «Palabras que organizan». Vamos a escuchar una explicación breve, elegir sus palabras más importantes y utilizarlas como guía para contarla. 📝$c$, perfil = $c$Preventivo. · Deterioro cognitivo leve. · Demencia leve, con información breve y palabras visibles.$c$, materiales = $c$Un texto de tres o cuatro frases, papel y lápiz. Opcionalmente, imágenes que representen las ideas principales.$c$, pasos = $c$["Lean un texto sencillo: «Para preparar una ensalada, primero lavamos los vegetales. Después los cortamos y los colocamos en un recipiente. Al final añadimos el aderezo».", "Pregunten: «¿Qué palabras nos ayudarían a explicar estos pasos?».", "Escriban juntas las palabras elegidas, por ejemplo: «lavar», «cortar», «mezclar».", "Manténganlas visibles y repasen su relación con el texto.", "Inviten a explicar la idea utilizando esas pistas.", "Vuelvan al texto cuando sea necesario. No hace falta repetirlo literalmente."]$c$::jsonb, ayuda = $c$Ofrezcan las palabras ya preparadas o utilicen imágenes. Construyan la explicación juntos, una idea por vez.$c$, adaptacion_por_etapa = $c${"preventivo": "utilizar un texto más amplio y permitir que seleccione sus propias palabras clave. Conversar sobre qué información puede dejar fuera sin perder el sentido.", "dcl": "presentar un texto corto y elegir juntos dos o tres palabras. Mantenerlas visibles durante la explicación.", "leve": "trabajar con una o dos frases y apoyos preparados por el familiar. Aceptar una explicación breve o completar juntos las ideas.", "moderada": "no utilizar como tarea de selección y resumen. Preferir palabras e imágenes vinculadas con una acción presente.", "avanzada": "no utilizar como tarea de selección y resumen. Preferir palabras e imágenes vinculadas con una acción presente."}$c$::jsonb, precaucion = $c$Elegir contenidos conocidos y acordes con la escolaridad y los intereses. Si leer o escribir resulta difícil, realizar toda la actividad oralmente o con imágenes. En el ejemplo de cocina, no es necesario manipular alimentos ni utensilios.$c$, ciencia = $c${"gancho": "¿Sabías que unas pocas palabras pueden servirnos de guía para explicar una idea?", "evidencia": "Elegir lo esencial nos ayuda a organizar la información sin tener que repetir cada frase.", "cierre": "Hoy vamos a crear nuestras propias pistas y utilizarlas para contar algo con nuestras palabras. Podemos escribirlas, dibujarlas o acompañarlas con imágenes. 📝🧠"}$c$::jsonb, extras = null, niveles_cognitivos = array[$c$preventivo$c$, $c$dcl$c$, $c$leve$c$]::text[], duracion = $c$De 5 a 10 minutos.$c$, frecuencia = $c$De 1 a 2 veces por semana.$c$, orden = 35, estado_clinico = 'aprobado', adaptacion = null, por_que = null, objetivo = null, progresion = null, requisito = null, dominios = null, updated_at = now() where codigo = $c$COG-035$c$;
insert into public.media_resources_interno (resource_id, objetivo, objetivo_esperado, areas_trabajo, progresion, reglas, etiquetas)
select id, $c$Practicar la selección de palabras clave y utilizarlas para organizar una explicación breve.$c$, $c$Facilitar que la persona organice y comunique una explicación breve apoyándose en palabras o imágenes seleccionadas.$c$, array[$c$Comprensión verbal$c$, $c$Identificación de ideas principales$c$, $c$Organización de información$c$, $c$Expresión oral$c$, $c$Uso de palabras clave$c$]::text[], $c$Usar una palabra como pista → organizar dos o tres ideas → elegir las palabras clave → explicar un contenido algo más extenso.$c$, $c$Mantener las pistas visibles. Ajustar la extensión y permitir participación oral, escrita o mediante imágenes.$c$, array[$c$Lenguaje$c$, $c$comprensión$c$, $c$palabras clave$c$, $c$organización$c$, $c$expresión oral$c$]::text[] from public.media_resources where codigo = $c$COG-035$c$
